import type { AnswerSet } from "@/lib/types";

import { withWrongExplanations } from "../../explanation-helpers";
import { explanations } from "./explanations";
import { questions } from "./questions";

// Answer key for y12-economics-global-economy. NO "server-only" import here (the
// validator reads it); only re-exported via content/answers/index.ts, which is server-only.
// Never import from a client component. This unit's ids are three digits (m001–m096,
// s001–s073), so the explanations helper is told the width is 3.
const U = "y12-economics-global-economy";

const keyWithoutExplanations: AnswerSet = Object.fromEntries([
  [`${U}.m001`, { correctText: "Country A has a higher real GDP and higher level of economic development than country B", rubric: ["Real GDP = nominal GDP ÷ CPI × 100. Country A: 390 ÷ 114 × 100 = $342.1b; Country B: 400 ÷ 120 × 100 = $333.3b, so Country A has the higher real GDP. Country A's HDI of 0.97 is above Country B's 0.75, so Country A also has the higher level of economic development."] }],
  [`${U}.m002`, { correctText: "Increased tax minimisation strategies and increased environmental degradation", rubric: ["TNCs are criticised for shifting profits to low-tax jurisdictions (tax minimisation) and for locating production where environmental regulation is weak, increasing environmental degradation. These are standard criticisms of TNCs in the global economy."] }],
  [`${U}.m003`, { correctText: "A transnational company establishes a subsidiary in another country", rubric: ["Foreign direct investment is investment by a firm in another country that gives it control or significant influence over an enterprise there. Establishing a subsidiary overseas is the classic example of FDI."] }],
  [`${U}.m004`, { correctText: "G20", rubric: ["The G20 is a forum of the leaders of the world's major economies that meets to coordinate policy across a broad agenda, including trade, health and climate. The other three are international organisations with narrower, specific mandates."] }],
  [`${U}.m005`, { correctText: "Government spending increases by $2000 and the price of milk falls by $10 a litre", rubric: ["The subsidy shifts supply down by $20 per litre. The price falls from $60 to $50 (a fall of $10) and quantity rises from 80 to 100 litres. Government spending on the subsidy = subsidy per unit × quantity = $20 × 100 = $2000."] }],
  [`${U}.m006`, { correctText: "When foreign firms sell their products in another country at a lower price than the selling price in the country of origin.", rubric: ["Dumping is selling exports in a foreign market at a price below the price charged in the exporter's home market (often below cost of production). Comparing the export price with the price in the country of origin is the defining feature."] }],
  [`${U}.m007`, { correctText: "Domestic producers' revenue will increase by $1200 and the government will receive $800 in taxation", rubric: ["At $20, domestic producers sell 20 units: revenue = 20 × $20 = $400. At $40, domestic producers sell 40 units: revenue = 40 × $40 = $1600. Increase = $1200. Imports fall from 80 units to 40 units, so the government collects tariff revenue of $20 × 40 = $800."] }],
  [`${U}.m008`, { correctText: "ASEAN", rubric: ["ASEAN (the Association of Southeast Asian Nations) is a regional bloc of Southeast Asian economies; Australia is a dialogue partner but not a member. Australia is a member of the CPTPP, APEC and ANZCERTA (the Closer Economic Relations agreement with New Zealand)."] }],
  [`${U}.m009`, { correctText: "A decrease in tariffs and an increase in a quota", rubric: ["Free trade grows when trade barriers fall. Lower tariffs reduce the cost of importing, and a larger quota (a higher quantitative ceiling on imports) lets more goods through — both expand the volume of trade."] }],
  [`${U}.m010`, { correctText: "Australian exporter revenue decreases and export volumes fall", rubric: ["Chinese subsidies lower the costs (and prices) of Chinese producers, making Chinese goods more competitive in markets that Australian exporters also sell to. Australian exporters face weaker demand, so both their export volumes and revenue fall."] }],
  [`${U}.m011`, { correctText: "200 units", rubric: ["A $2 tariff raises the domestic price from 6 to 8. At price 8, domestic demand is 400 units and domestic supply is 200 units, so imports are 400 − 200 = 200 units. A quota set at 200 units would restrict imports to exactly this quantity, so it has the same effect on price as the $2 tariff."] }],
  [`${U}.m012`, { correctText: "World Bank", rubric: ["The World Bank provides long-term, low-interest loans and grants to developing countries for development projects, including hospitals, schools and infrastructure. That is its core lending role."] }],
  [`${U}.m013`, { correctText: "$1000", rubric: ["The subsidy per unit is the vertical distance between the original supply curve S and the post-subsidy supply curve S1, which is $20. The new quantity traded is 50 units. Total cost to the government = subsidy per unit × quantity = $20 × 50 = $1000."] }],
  [`${U}.m014`, { correctText: "AANZFTA", rubric: ["The ASEAN–Australia–New Zealand Free Trade Area (AANZFTA) is a multilateral FTA — it covers the ten ASEAN members plus Australia and New Zealand — and Australia is a party to it. The other options are blocs or agreements Australia is not a member of (EU, USMCA) or that are bilateral (ChAFTA)."] }],
  [`${U}.m015`, { correctText: "The International Monetary Fund", rubric: ["The IMF's purpose is to promote international monetary cooperation and provide temporary financial assistance to member countries experiencing balance of payments difficulties, helping stabilise their exchange rates."] }],
  [`${U}.m016`, { correctText: "Increase in tariffs on imported goods — Decrease in quotas on imported goods", rubric: ["A tariff protects by raising the price of imports, so tariffs should increase. A quota is the maximum quantity that may be imported, so protection increases when the quota is decreased (fewer imports allowed in). The protective combination is higher tariffs and lower quotas."] }],
  [`${U}.m017`, { correctText: "High population growth rates, low per capita incomes and low levels of capital accumulation", rubric: ["Rapid population growth, low incomes per person and little capital accumulation each constrain growth and development: fast population growth dilutes output gains, low incomes limit saving and demand, and low capital formation limits productive capacity."] }],
  [`${U}.m018`, { correctText: "World Bank", rubric: ["The World Bank lends to developing countries for development projects, including building schools and other educational facilities, and provides technical assistance for education."] }],
  [`${U}.m019`, { correctText: "Greater levels of rural to urban migration.", rubric: ["Economic development involves structural change — a shift of resources out of low-productivity agriculture into industry and services. Rural-to-urban migration is a sign of this structural transformation and of rising living standards."] }],
  [`${U}.m020`, { correctText: "Government Revenue $10,000 — Foreign Producer Revenue $20,000 — Subsidy Value $5 per unit", rubric: ["The $5 tariff cuts imports from 4000 to 2000 units. Government revenue = tariff × imports = $5 × 2000 = $10,000. Foreign producers now sell only 2000 units at the world price of $10, so their revenue = $10 × 2000 = $20,000. A subsidy of $5 per unit to domestic producers would shift supply down by $5 and have the same effect on the market as the $5 tariff."] }],
  [`${U}.m021`, { correctText: "Price after quota 12 — Overseas producer revenue after quota 24 000", rubric: ["The quota restricts imports to 2000 units, so the domestic price rises from the world price of $10 to $12. The overseas producer now sells the 2000-unit quota quantity into the domestic market at the higher price, so its revenue after the quota is 12 × 2000 = $24,000. Both the price after the quota (12) and the revenue (24 000) match option D."] }],
  [`${U}.m022`, { correctText: "They can lead to trade diversion from efficient non-member countries to inefficient member countries.", rubric: ["A trade bloc gives preferential treatment to its members, so trade can be diverted away from lower-cost non-member producers toward higher-cost member producers. Trade diversion is a recognised disadvantage of trade blocs."] }],
  [`${U}.m023`, { correctText: "Integration in the international business cycle makes countries vulnerable due to specialisation.", rubric: ["Under free trade countries specialise; that specialisation ties each economy to the international business cycle, so a downturn in partner economies transmits to the specialised economy. This transmission of fluctuations is a standard disadvantage of free trade."] }],
  [`${U}.m024`, { correctText: "Provide funds to pay for childhood vaccination programs.", rubric: ["The table shows a very low life expectancy at birth of 40 years. Childhood vaccination directly attacks the cause of low life expectancy, so it is the measure most likely to raise life expectancy and thereby improve the country's economic development. The World Bank funds such development projects."] }],
  [`${U}.m025`, { correctText: "Revenue decreases by $60,000 — Demand expands along the demand curve due to lower price from $4 to $3", rubric: ["The tariff cut raises imports from 20,000 to 40,000 units, so the domestic price falls by $1 from $4 to $3. At $4 domestic supply is 30,000 units (revenue 4 × 30,000 = $120,000); at $3 domestic supply is 20,000 units (revenue 3 × 20,000 = $60,000). Domestic producers' revenue therefore falls by $60,000, while consumers move down the demand curve as the price falls (demand expands from 50,000 to 60,000 units)."] }],
  [`${U}.m026`, { correctText: "Loss of competitiveness due to exchange rate inflexibility for individual members.", rubric: ["In a monetary union the exchange rate is set for the union as a whole, so an individual member cannot depreciate its currency to restore competitiveness when its costs rise. This loss of the exchange-rate adjustment mechanism is the main disadvantage of monetary union membership."] }],
  [`${U}.m027`, { correctText: "Developing", rubric: ["Developing economies typically have low domestic savings rates and remain heavily dependent on agricultural and primary exports. The description in the stem matches the standard characteristics of a developing economy."] }],
  [`${U}.m028`, { correctText: "Increase real incomes and living standards", rubric: ["Economic development is a broad improvement in wellbeing — real incomes and living standards. Globalisation lifts average real incomes by expanding markets, spreading technology and lowering prices, so this option directly links globalisation to development outcomes rather than to intermediate measures."] }],
  [`${U}.m029`, { correctText: "A loss of skilled labour from developing countries", rubric: ["The international division of labour has firms and workers specialising across countries. As production becomes integrated, skilled workers migrate from developing to advanced economies (brain drain), which is a well-documented consequence of the deepening international division of labour."] }],
  [`${U}.m030`, { correctText: "Local content rules", rubric: ["Local content rules require firms to use a certain proportion of domestically produced inputs or services in their output. Requiring businesses to use domestic inputs is the defining feature of local content rules."] }],
  [`${U}.m031`, { correctText: "European Union", rubric: ["A monetary union is a group of economies that share a common currency and a single monetary policy. Twenty EU members share the euro and the European Central Bank's monetary policy, so the EU (through its eurozone) is the standard example of a monetary union."] }],
  [`${U}.m032`, { correctText: "Developing economy", rubric: ["An agrarian economy with high population growth, low economic development and weak integration with global markets matches the standard characteristics of a developing economy."] }],
  [`${U}.m033`, { correctText: "Multilateral agreement", rubric: ["A common trade policy agreed by a group of regional economies is a multilateral arrangement — it involves more than two parties acting together. This description matches a multilateral (regional) trade agreement."] }],
  [`${U}.m034`, { correctText: "Gross Domestic Product (GDP)", rubric: ["The HDI is built from life expectancy at birth, education (mean years of schooling and expected years of schooling) and gross national income per capita. GDP is the aggregate-income measure used in national accounts; the HDI specifically uses GNI per capita, so GDP is not one of its indicators."] }],
  [`${U}.m035`, { correctText: "Comparative advantage", rubric: ["International trade is explained by comparative advantage: countries gain by specialising in producing the goods they can produce at relatively lower opportunity cost. Comparative advantage is the theoretical foundation of free trade."] }],
  [`${U}.m036`, { correctText: "The International Monetary Fund", rubric: ["The IMF provides temporary financial assistance to member countries facing balance of payments problems, including to help stabilise the exchange rate when a global recession causes external pressure. That is precisely its stated role."] }],
  [`${U}.m037`, { correctText: "The World Bank", rubric: ["The World Bank's core mandate is to reduce poverty and support economic development in poorer countries through loans, grants and technical assistance, so it is the organisation most directly concerned with developing countries' development."] }],
  [`${U}.m038`, { correctText: "A broad measure of welfare in an economy including indicators of health, education, environmental quality, and material living standards", rubric: ["Economic development is broader than growth: it measures improvements in people's welfare, including health, education, environmental quality and material living standards. Only this option captures that breadth."] }],
  [`${U}.m039`, { correctText: "A subsidy can lower prices for consumers while a tariff can not", rubric: ["A per-unit subsidy to domestic producers shifts the supply curve down, which can lower the price consumers pay, whereas a tariff raises the domestic price above the world price. That is the key difference in the effect of the two policies on consumers."] }],
  [`${U}.m040`, { correctText: "Increases in the value of global trade as a proportion of total output", rubric: ["Globalisation is the growing integration of economies through trade and financial flows. The clearest single indicator of expanding globalisation is a rise in world trade as a share of total world output, since it shows economies becoming more trade-interdependent over time."] }],
  [`${U}.m041`, { correctText: "Different nations that specialise in different types of production and labour", rubric: ["The international division of labour is the specialisation of different nations in different types of production and labour as global production becomes integrated. This is the standard definition of the term."] }],
  [`${U}.m042`, { correctText: "The average life expectancy at birth for OECD countries exceeds 80 years", rubric: ["The HDI is built from life expectancy at birth, education and income per person. Life expectancy at birth is one of its three dimensions, and for OECD countries the HDI is high with average life expectancy at birth above 80 years, so this is the only option that relates to what the HDI actually measures."] }],
  [`${U}.m043`, { correctText: "Domestic supply rises from Q1 to Q2", rubric: ["The tariff raises the domestic price from the free trade price F to the tariff price T. At the higher price, domestic producers supply more, so domestic supply rises from Q1 (at F) to Q2 (at T)."] }],
  [`${U}.m044`, { correctText: "NAFTA", rubric: ["NAFTA (the North American Free Trade Agreement) is an agreement between the United States, Canada and Mexico; Australia is not a party to it. Australia is a member of the WTO and the OECD, and is a party to CER (the Closer Economic Relations agreement with New Zealand, also written CERTA)."] }],
  [`${U}.m045`, { correctText: "A fall in barriers to labour mobility", rubric: ["Globalisation involves the growing integration of economies, including the freer movement of labour across borders. Falling barriers to labour mobility are a recognised trend of globalisation."] }],
  [`${U}.m046`, { correctText: "An increase in multi-lateral trade agreements involving developing nations", rubric: ["Multilateral trade agreements that include developing nations open export markets and support growth and development in poorer countries, which tends to narrow the gap in the global distribution of income."] }],
  [`${U}.m047`, { correctText: "$40,000", rubric: ["At the world price of $2, domestic supply is 10 000 and demand is 70 000, so imports are 60 000. A quota of 40 000 raises the price until demand minus supply equals 40 000: at $3, demand is 60 000 and supply is 20 000. The equivalent tariff is therefore $1 per unit, and revenue is $1 × 40 000 imports = $40 000."] }],
  [`${U}.m048`, { correctText: "Investment", rubric: ["The global movement of capital refers to international financial flows, that is, the movement of investment (debt and equity) across borders. It is one of the main financial flows of globalisation."] }],
  [`${U}.m049`, { correctText: "GDP per capita at purchasing power parity, years of schooling, life expectancy at birth", rubric: ["The HDI combines a health dimension (life expectancy at birth), an education dimension (years of schooling) and an income dimension (income per person). This option contains the education and health measures that are the core HDI components."] }],
  [`${U}.m050`, { correctText: "Export incentives", rubric: ["Export incentives are government measures that assist domestic firms to sell into overseas markets, such as financial assistance, information and advice. Encouraging businesses to penetrate new markets with financial assistance and legal information is the defining feature of export incentives."] }],
  [`${U}.m051`, { correctText: "When it can produce a good with a lower opportunity cost than another country", rubric: ["Comparative advantage is defined by opportunity cost: a country has a comparative advantage in a good when it can produce it at a lower opportunity cost than its trading partners. This is the theoretical basis of free trade."] }],
  [`${U}.m052`, { correctText: "Decreased domestic prices and improved international competitiveness for Australian goods", rubric: ["A subsidy lowers domestic producers' costs, shifting the supply curve down. This lowers the domestic price and makes domestic goods more competitive against imports, improving international competitiveness."] }],
  [`${U}.m053`, { correctText: "The total sum of economic activity of the world", rubric: ["Gross World Product is the total value of all goods and services produced in the world economy, that is, the sum of economic activity of the world as a whole."] }],
  [`${U}.m054`, { correctText: "To help fund investment in infrastructure", rubric: ["The World Bank's main role is to provide loans and grants to developing countries for development projects, including infrastructure such as roads, power and schools. Funding investment in infrastructure is its core lending function."] }],
  [`${U}.m055`, { correctText: "Small services sector, high population growth rates, less advanced manufacturing", rubric: ["Emerging and developing economies typically have a small services sector, high population growth rates and less advanced manufacturing, reflecting their lower level of industrialisation and development."] }],
  [`${U}.m056`, { correctText: "Domestic producers' market share will increase and the price of domestic products may rise", rubric: ["A tighter import quota (the supply curve shifting from S to S1) reduces the quantity of imports, so domestic producers supply a larger share of the market. With fewer imports available, the domestic price of the product may rise."] }],
  [`${U}.m057`, { correctText: "Moderate growth — Heavily reliant on agriculture — Income levels are low", rubric: ["Developing economies typically experience moderate economic growth, remain heavily reliant on agriculture, and have low income levels. This combination matches the standard characteristics of a developing economy."] }],
  [`${U}.m058`, { correctText: "$1000", rubric: ["The subsidy per unit is the vertical distance between the original supply curve S and the post-subsidy supply curve S1, which is $20. The new quantity traded is 50 units, so the total value of the subsidy payable by the government is $20 × 50 = $1000."] }],
  [`${U}.m059`, { correctText: "Imports Increase — Government revenue Decrease", rubric: ["Removing the $5 tariff lowers the domestic price from $105 to $100, so imports rise from 100 to 200 units. The government no longer collects the tariff, so its revenue from the tariff falls to zero."] }],
  [`${U}.m060`, { correctText: "An increase in real gross domestic product per capita and an increase in life expectancy", rubric: ["Economic development is broader than growth: it includes improvements in wellbeing such as health and living standards. An increase in real GDP per capita combined with an increase in life expectancy shows both rising incomes and better health, which best supports an improvement in economic development."] }],
  [`${U}.m061`, { correctText: "$4", rubric: ["Under free trade at $2, imports are 70 000 − 10 000 = 60 000, so overseas producers earn $2 × 60 000 = $120 000. To cut that by $80 000 to $40 000, imports must fall to 20 000. A subsidy leaves the price at $2 but lets domestic producers supply as if they received $2 + subsidy. Imports of 20 000 need domestic supply of 50 000, which the supply curve gives at $6, so the subsidy is $6 − $2 = $4."] }],
  [`${U}.m062`, { correctText: "The promotion of global monetary stability and lending to crisis-affected countries", rubric: ["The IMF's core functions are promoting global monetary stability and lending to countries in balance-of-payments difficulties, such as crisis-affected countries. This is the option that correctly names TWO major IMF functions."] }],
  [`${U}.m063`, { correctText: "EU", rubric: ["The EU is a trading bloc (a single market and customs union with free movement of goods, services, capital and labour), and its eurozone members share the euro and one monetary policy, making it a monetary union as well."] }],
  [`${U}.m064`, { correctText: "Production output: Increases | Price level: Decreases", rubric: ["A subsidy lowers producers' costs, shifting the supply curve to the right. Production output increases while the price level decreases, which is the combination shown in the correct option."] }],
  [`${U}.m065`, { correctText: "Price of product: $60 | Government revenue: Increases | Change in domestic producer revenue: $1400", rubric: ["A $10 tariff on a $50 world price raises the domestic price to $60, the same price the quota produced. The tariff generates government revenue (unlike the quota), so government revenue increases. At $60 the domestic quantity supplied is 40 million, so producer revenue is $60 × 40m = $2400m; under free trade at $50 the domestic quantity supplied is 20 million, so producer revenue was $50 × 20m = $1000m. The change in domestic producer revenue is therefore $2400m − $1000m = $1400m."] }],
  [`${U}.m066`, { correctText: "Low level of inequality", rubric: ["Developing economies are typically characterised by high inequality, with income and wealth concentrated among a small share of the population. A low level of inequality is therefore NOT a typical characteristic of a developing economy."] }],
  [`${U}.m067`, { correctText: "World Bank", rubric: ["The World Bank Group's twin goals include ending extreme poverty, defined as reducing the share of the world's population living in extreme poverty to below 3% by 2030. This matches the aim stated in the question."] }],
  [`${U}.m068`, { correctText: "Global factor: Tied aid | Domestic factor: Poor access to capital", rubric: ["Tied aid is a global factor that can hold down a developing economy's income, and poor access to capital is a domestic factor that also keeps national income low. This is the only combination in which both listed factors are genuine causes of low levels of national income."] }],
  [`${U}.m069`, { correctText: "More regulation of financial sectors", rubric: ["The international business cycle is reinforced by movements in trade, financial flows, technology flows and investment relative to the global economy. More regulation of financial sectors reduces financial flows between economies, weakening rather than strengthening the international business cycle."] }],
  [`${U}.m070`, { correctText: "BCML + EFRN", rubric: ["Removing the tariff lowers the domestic price from the with-tariff price to the world price, increasing the quantity of imports. Foreign producers gain net income from the increased quantity of exports they sell once the tariff is removed, which the school's solutions mark as the areas BCML + EFRN."] }],
  [`${U}.m071`, { correctText: "Increased access to affordable and innovative products and new markets", rubric: ["Globalisation integrates markets, so consumers gain cheaper and newer imported products and firms gain access to new export markets. The other three options are costs of globalisation."] }],
  [`${U}.m072`, { correctText: "Business closures in some industries due to strong foreign competition", rubric: ["Free trade agreements remove protection, so inefficient import-competing firms face stronger foreign competition and some close. The other three options are advantages for domestic producers."] }],
  [`${U}.m073`, { correctText: "A decrease of 40 million units", rubric: ["At the $50 world price, imports are demand minus domestic supply: 100 − 20 = 80 million. At $60, imports are 80 − 40 = 40 million. Imports fall by 80 − 40 = 40 million units."] }],
  [`${U}.m074`, { correctText: "Country A has become more integrated into the global economy than Country B, because its trade and financial flows have both risen by a larger amount.", rubric: ["Interdependence is measured by the openness of an economy to trade and financial flows. Country A's exports rose from 18% to 34% of GDP (a 16-point rise) and imports from 20% to 36% (a 16-point rise), while its FDI inflows rose from 1.5% to 6.0% and portfolio inflows from 0.8% to 4.5%. Country B's trade shares rose only 3 points each and its financial flows barely moved. Country A's trade and financial flows both grew far more, so it has become more integrated."] }],
  [`${U}.m075`, { correctText: "Trade growth is more volatile than output growth, and the two move together, which shows economies are interdependent.", rubric: ["Across the four years, world trade volume growth swings from +5.5% to −5.3% to +9.8%, a much wider range than output growth (from +3.2% to −3.0% to +6.3%). Trade and output fall together in Year 3 and rebound together in Year 4, which is the signature of interdependence: a world downturn cuts trade and output simultaneously, and the recovery lifts both."] }],
  [`${U}.m076`, { correctText: "The economy is becoming more open and therefore more exposed to changes in the global economy.", rubric: ["The trade-to-GDP ratio (exports plus imports as a share of GDP) is the standard measure of openness. It rises steadily from 40% to 61%, so the economy is trading a larger share of its output. A more open economy is more exposed to global shocks — a fall in world demand or a rise in world prices transmits more strongly to it — so it is more interdependent."] }],
  [`${U}.m077`, { correctText: "Advanced economies receive about two-thirds of world FDI inflows, so financial interdependence is concentrated among richer economies.", rubric: ["In Year 2, advanced economies receive 950 of 1430 billion, which is about 66% (two-thirds); emerging and developing economies receive 480 of 1430, about 34%. FDI is a financial flow, and its concentration among advanced economies shows that financial interdependence is unevenly distributed, favouring richer economies."] }],
  [`${U}.m078`, { correctText: "A forum of the world's largest economies that coordinates global economic policy but whose agreements are not legally binding.", rubric: ["The G20 is a government economic forum of the 19 largest economies plus the EU (and the African Union since 2023). It coordinates policy through summits and communiqués, but it has no permanent secretariat and its agreements are not binding — unlike the IMF, a trading bloc, or a monetary union."] }],
  [`${U}.m079`, { correctText: "The G20 is an informal forum whose decisions are not binding, whereas the IMF is a formal organisation with binding lending conditions.", rubric: ["The G20 is an informal forum of heads of government that coordinates policy but cannot bind its members. The IMF is a formal international organisation that lends to countries in balance-of-payments crisis and attaches conditions (conditionality) to that lending. This is the core structural difference between a forum and an organisation."] }],
  [`${U}.m080`, { correctText: "coordinating a shared policy response to a global shock, which boosted confidence and supported the recovery.", rubric: ["The 2009 G20 response to the GFC (the London Summit) was a coordinated agreement by member governments to stimulate their economies together. Because the G20 is a forum, this was coordination, not legislation or lending; the shared stimulus supported demand and confidence during the crisis."] }],
  [`${U}.m081`, { correctText: "the total market value of all final goods and services produced in the world in a year.", rubric: ["GWP is the \"world's GDP\": the total market value of all final goods and services produced in the world in a year. It measures production, not trade, government spending or financial flows."] }],
  [`${U}.m082`, { correctText: "It is the sum of all national economies and the international economic relationships linking them.", rubric: ["The global economy is the sum of all national economies plus the international economic relationships — trade, finance, investment and labour — that link them. It is not limited to trade, to advanced economies, or to investment."] }],
  [`${U}.m083`, { correctText: "PPP adjusts for the fact that goods and services are cheaper in emerging economies, so their real output is larger than market exchange rates suggest.", rubric: ["Market exchange rates convert each country's output into a common currency at the going exchange rate, which understates emerging economies because their non-traded goods and services are cheap. PPP uses prices of a common basket of goods to compare real purchasing power, so emerging economies' real output is larger than the market-rate measure suggests, raising their share of world output."] }],
  [`${U}.m084`, { correctText: "Export-oriented industrialisation, using its low-cost labour to produce manufactured goods for world markets.", rubric: ["With a small domestic market, Country X cannot grow by selling only at home, so import substitution (which relies on the home market) is limited. Its abundant low-cost labour gives it a comparative advantage in labour-intensive manufacturing, which export-oriented industrialisation exploits by selling into large world markets — the East Asian model (China, South Korea, Vietnam) that has delivered rapid growth and development."] }],
  [`${U}.m085`, { correctText: "it can raise growth and employment, but profits may be repatriated and tax revenue forgone.", rubric: ["A special economic zone attracts FDI by offering tax breaks and regulatory ease, which can create jobs, transfer technology and lift exports. The trade-off is that the tax concessions forgo government revenue, and foreign firms may repatriate profits rather than reinvest them locally, so the benefits are not fully captured by the host economy."] }],
  [`${U}.m086`, { correctText: "The international business cycle is the tendency for many economies worldwide to experience booms and contractions at similar times, whereas a regional business cycle is co-movement within a specific region.", rubric: ["The international business cycle is world-wide synchronisation of booms and contractions across many economies, while a regional business cycle is the co-movement of economies within a particular region (for example East Asia or the euro area) that trade closely with one another. The distinction is one of scope: worldwide versus within a region."] }],
  [`${U}.m087`, { correctText: "a fall in the major economy's imports, which reduces demand for its partners' exports, lowering their output and employment.", rubric: ["When a major economy enters a downturn, its income and spending fall, so it imports less. Its trading partners then export less, which reduces their output and employment, and the downturn spreads. This is the trade channel of transmission, the core mechanism of the international business cycle."] }],
  [`${U}.m088`, { correctText: "The emerging economy may be driven by different factors, such as commodity prices or domestic investment, so its cycle need not move in step with advanced economies.", rubric: ["Business cycles are not perfectly synchronised. An emerging economy whose growth depends on commodity exports or domestic investment can boom or contract for reasons unrelated to advanced economies, so its cycle can diverge from theirs. Synchronisation varies by shock and region, and emerging economies can also be hit harder by global credit tightening."] }],
  [`${U}.m089`, { correctText: "Income is the flow of earnings received over a period, whereas wealth is the stock of assets owned at a point in time.", rubric: ["Income is a flow — the earnings (wages, profits, rent, interest) received over a period such as a year. Wealth is a stock — the value of assets (financial and non-financial) owned at a point in time. Wealth is always more unequally distributed than income, because assets accumulate over time."] }],
  [`${U}.m090`, { correctText: "Inequality between countries has fallen this century as China and India have converged, while inequality within many advanced economies has tended to rise.", rubric: ["The key nuance is that between-country inequality has fallen this century because large emerging economies (China, India) have grown faster than advanced economies, narrowing the gap between countries. At the same time, inequality within many advanced economies has tended to rise. A flat statement that \"global inequality is rising\" misses this distinction."] }],
  [`${U}.m091`, { correctText: "Reduced human capital and social problems in poor countries, and political instability that can slow growth.", rubric: ["A highly unequal distribution means many people lack the income to invest in health and education, so human capital is reduced; poverty is associated with social problems and political instability, which can slow or destabilise growth. These are the standard consequences of global inequality."] }],
  [`${U}.m092`, { correctText: "Trade and foreign investment have grown, and transnational corporations have expanded production across many countries.", rubric: ["Globalisation has increased trade in goods and services and cross-border investment, and transnational corporations have grown by locating production, distribution and research across many countries. TNCs are the main conduit of foreign direct investment, so their expansion and the growth of trade and investment go together."] }],
  [`${U}.m093`, { correctText: "It tends to raise growth and average living standards, but the benefits are unevenly distributed.", rubric: ["Globalisation raises growth and average living standards through more trade, investment and technology transfer, but the gains are not shared equally — some industries and workers lose out, and some countries benefit more than others. A Band 6 answer recognises both the average gain and the uneven distribution."] }],
  [`${U}.m094`, { correctText: "Development raises resource use and emissions, but it also funds green technology and international agreements that can reduce environmental damage.", rubric: ["Continuing world economic development increases resource use and emissions (a negative externality), but the higher incomes it generates fund green technology, renewable energy and international agreements (Kyoto, Paris) that can reduce environmental damage. The standard answer needs both the environmental cost and the policy/technology response."] }],
  [`${U}.m095`, { correctText: "inefficient domestic firms with little incentive to improve, because they face no foreign competition and cannot achieve economies of scale.", rubric: ["Import substitution protects domestic industry from foreign competition, which removes the incentive to become efficient and, in a small home market, prevents firms from reaching economies of scale. This is why import substitution has largely failed in practice, producing high-cost, inefficient industries."] }],
  [`${U}.m096`, { correctText: "Increasing investment in education and health.", rubric: ["Human capital is the skills, knowledge and health of the workforce. Investment in education and health directly builds human capital, raising productivity and supporting development. The other options are trade or investment strategies that do not directly target human capital."] }],
  [`${U}.s001`, { modelAnswer: "A trade bloc is a group of countries that join together in a formal preferential trading agreement, to the exclusion of other countries, for example the EU. A monetary union is where two or more countries share a common currency, for example where the euro is used by several countries in Europe.", rubric: ["1. States that a trade bloc is a number of countries joining together in a formal preferential trading agreement to the exclusion of other countries (e.g. the EU).", "2. States that a monetary union is where two or more countries share a common currency (e.g. the euro)."], notes: "Both definitions must be correct for 2 marks; defining either a trade bloc or a monetary union alone earns 1 mark. The distinguishing feature is the shared currency: a monetary union adds a common currency (and single monetary policy) to bloc-style integration." }],
  [`${U}.s002`, { modelAnswer: "The IMF's main goal is to ensure the stability of the international monetary and financial system. During an international business cycle downswing, it helps resolve crises by lending to member countries facing balance-of-payments difficulties, and it works with member countries to promote growth and alleviate poverty. For example, Greece received three bailouts during the EU debt crisis.", rubric: ["1. Outlines a role of the IMF: ensuring the stability of the international monetary and financial system.", "2. Explains how that role operates during an international business cycle downswing (helping to resolve crises and lending to crisis-affected countries).", "3. Provides a specific example of a country that received IMF assistance during a downturn (e.g. Greece and its three bailouts during the EU debt crisis)."], notes: "The example must be a real country that received a bailout or other IMF assistance. A role with no example, or an example with no role, earns at most 1 mark. Acceptable roles: crisis resolution, lending to countries in balance-of-payments difficulty, promoting growth and alleviating poverty." }],
  [`${U}.s003`, { modelAnswer: "Ecologically sustainable development is development that meets the needs of present generations while not compromising the ability of future generations to also meet their needs.", rubric: ["1. Defines ecologically sustainable development as development that meets the needs of present generations without compromising the ability of future generations to meet their needs."], notes: "The intergenerational element (present needs without sacrificing future generations' ability to meet theirs) must be in the definition; a vague mention of \"protecting the environment\" without the future-generation idea earns nothing." }],
  [`${U}.s004`, { modelAnswer: "For example, in China, rapid export-led industrialisation driven by globalisation expanded coal-based electricity generation and manufacturing, making China the world's largest emitter of carbon dioxide and creating serious air pollution. China has addressed this by introducing a national emissions trading scheme (launched in 2021), which prices carbon and raises the cost of the most emissions-intensive production, and by rapidly expanding renewable energy such as solar, reducing the emissions intensity of its growth.", rubric: ["1. Names an economy other than Australia and describes a specific impact of globalisation on its environmental sustainability (e.g. higher emissions or pollution from export-led industrialisation).", "2. Explains how the impact follows from globalisation (greater trade, foreign investment and TNC production increasing resource use and emissions).", "3. Describes one strategy the country has used to address the impact (e.g. an emissions trading scheme or renewable energy expansion).", "4. Explains how that strategy works to address the environmental impact."], notes: "Any suitable economy other than Australia is acceptable (China, India, Vietnam, Indonesia, etc.); the rubric does not require a specific one. A correct answer must name the economy, link the environmental impact to globalisation, and give a genuine strategy with a mechanism. \"Describe\" requires depth, not evaluation. Sketching one impact or one strategy only earns at most 1 mark." }],
  [`${U}.s005`, { modelAnswer: "Subsidies are payments made by the government to domestic producers to lower their costs of production, giving them a cost advantage over imports. Local content rules are requirements set by a government for certain industries, stipulating a minimum percentage of a product or service that must be produced locally.", rubric: ["1. States that subsidies are payments to domestic producers that lower their costs of production.", "2. States that local content rules are government requirements stipulating a minimum percentage of a product or service that must be produced locally."], notes: "Both are forms of protection but work differently: subsidies are direct government payments that cut producers' costs, while local content rules mandate a minimum share of local production. Both must be correct for 2 marks; describing one correctly earns 1 mark." }],
  [`${U}.s006`, { modelAnswer: "First, decreased subsidies reduce government spending on subsidies, which pushes the budget towards surplus. Second, they can lower tax revenue from previously subsidised firms that become less profitable, and may increase government spending on unemployment benefits or education and training for workers who lose their jobs in the previously subsidised industry.", rubric: ["1. Outlines one impact of decreased subsidies on the government's budget (e.g. lower spending on subsidies, pushing the budget towards surplus; lower tax revenue from previously subsidised firms; or higher spending on unemployment benefits and retraining).", "2. Outlines a second, different impact on the government's budget from the same list."], notes: "The marking guideline accepts any two of: reduced government spending (budget towards surplus), lower tax revenue from previously subsidised firms, or higher welfare/unemployment and retraining spending. Answers must stay on the government's budget; effects on the industry's profits or consumer prices do not earn the mark." }],
  [`${U}.s007`, { modelAnswer: "The IMF was created to foster global monetary cooperation and to provide a platform for dialogue and consultation on international monetary issues. It provides temporary financial assistance to countries to help ease balance-of-payments adjustment, typically in the form of loans that come with policy conditions aimed at addressing economic vulnerabilities.", rubric: ["1. Outlines one role of the IMF in the global economy (e.g. fostering monetary cooperation and stability of the international monetary system; surveillance of member economies and policy advice; temporary lending to countries with balance-of-payments problems; technical assistance).", "2. Gives detail on that role or outlines a second role (e.g. that IMF loans usually come with policy conditions aimed at fixing the borrower's economic vulnerabilities)."], notes: "The role must be the IMF's own. Swapping in the World Bank's (development loans) or the WTO's (trade dispute resolution) role earns nothing; naming the IMF without any role earns at most 1 mark." }],
  [`${U}.s008`, { modelAnswer: "Globalisation refers to the greater level of economic integration between different countries and regions of the world, driven by the growth of free trade, flows of foreign investment, improvements in technology and more efficient transport.", rubric: ["1. States the correct meaning of globalisation as the greater level of economic integration between different countries and regions of the world."], notes: "The definition must convey economic integration/interconnectedness of economies. Naming free trade or technology alone without the integration idea is too narrow to earn the mark." }],
  [`${U}.s009`, { modelAnswer: "Due to the increase in globalisation and the greater level of economic integration, changes in the economic performance of countries and regions are now more interrelated. This interrelationship through trade, financial and investment flows means that changes in economic growth in the major economies of the world are more harmonised, as was evident during the Global Financial Crisis, when the downturn in the United States spread to other countries and regions, including Europe, China and Japan, through the transmission of financial contagion.", rubric: ["1. Explains that globalisation has made economies more interrelated through trade, financial and investment flows, so changes in economic growth in major economies are more harmonised.", "2. Supports the explanation with an example of international transmission of the cycle (e.g. the Global Financial Crisis spreading from the United States to Europe, China and Japan)."], notes: "Markers reward the transmission mechanism (trade, financial and investment flows) plus an example. A general description of globalisation with no link to the business cycle, or no example, earns at most 1 mark." }],
  [`${U}.s010`, { modelAnswer: "One consequence is widespread poverty and very low incomes in low-income economies: the World Bank classes economies with a GNI per capita of about US$1,145 or less as low income, against more than about US$14,005 for high income (FY2025 thresholds), so large shares of their populations live in poverty. A second consequence is poorer human development: people in low-income economies have lower life expectancy, lower adult literacy rates and lower daily calorie intake than people in high-income economies, which compounds the gap between rich and poor nations.", rubric: ["1. Describes one economic consequence of unequal global distribution, such as widespread poverty and very low incomes in low-income economies.", "2. Describes a second, different consequence, such as lower life expectancy, literacy or daily calorie intake (poorer health and human capital) in low-income economies."], notes: "Both consequences must be consequences of inequality (poverty, poor health, lower literacy, hunger, weaker human capital, uneven wealth); stating the causes of inequality or restating inequality itself (\"the rich get richer\") earns nothing. One consequence earns at most 1 mark." }],
  [`${U}.s011`, { modelAnswer: "Global inequalities are caused by a combination of global and domestic factors. Global factors include the structure of the global trade system and financial architecture, which tend to favour advanced economies, unequal access to global technology flows, and the limited scale of global aid and assistance. Domestic factors include economic resources — the quantity and quality of natural resources, labour supply and quality, and access to capital — and institutional factors such as the quality of political and economic institutions and the economic policies countries adopt. These factors interact: countries with weak institutions and low human capital struggle to attract investment and participate in global trade, so the gap between rich and poor nations persists. The result is a highly unequal global distribution: the top 10% of the world's population receives around half of global income, while the bottom 50% receives under a tenth.", rubric: ["1. States that global inequalities are caused by a combination of global and domestic factors.", "2. Explains a global factor (e.g. the global trade system and financial architecture, unequal access to technology flows, or limited aid).", "3. Explains a domestic economic-resource factor (e.g. natural resources, labour supply and quality, or access to capital).", "4. Explains a domestic institutional factor (e.g. political and economic institutions, or economic policies).", "5. Discusses the interaction of these factors or supports the discussion with evidence on the global distribution of income and wealth."], notes: "\"Discuss\" requires more than listing: the top band needs a clear and concise discussion, so factors should be explained and linked, not just named. Global and domestic factors both count; a response covering only one side can still earn up to 3 marks. Data on the global distribution (e.g. the top 10% receiving about half of global income) strengthens the discussion but is not essential for full marks." }],
  [`${U}.s012`, { modelAnswer: "The IMF contributes to the global economy by providing financial assistance to member countries experiencing balance-of-payments crises, lending them funds to stabilise their economies and restore investor confidence — for example, its emergency financing during the COVID-19 pandemic.", rubric: ["1. Outlines one specific contribution of the IMF to the global economy (e.g. lending to countries in balance-of-payments crisis, promoting monetary cooperation, facilitating the expansion of trade, or promoting exchange-rate stability).", "2. Gives detail on that contribution (e.g. that the loans help stabilise the economy and restore confidence, or that they come with policy conditions)."], notes: "The contribution must be the IMF's own; the World Bank's development lending or the WTO's trade-dispute role earns nothing. Naming the IMF without a contribution, or giving only a general statement, earns at most 1 mark." }],
  [`${U}.s013`, { modelAnswer: "Comparative advantage means that each country specialises in producing the goods and services it can produce at the lowest opportunity cost. This specialisation allows countries to achieve economies of scale and greater productivity. As a result, resources such as labour, capital and land are reallocated towards the industries in which each country is relatively most efficient, so the world's resources are used more efficiently and total world output rises.", rubric: ["1. Explains that comparative advantage leads countries to specialise in producing goods at the lowest opportunity cost.", "2. Explains that specialisation leads to economies of scale and greater productivity.", "3. Explains that this reallocates resources to their most efficient uses globally, improving the global allocation of resources and raising total world output."], notes: "The answer must relate cause and effect (comparative advantage → specialisation → productivity → better global resource allocation) for full marks. Using absolute advantage instead of comparative advantage earns nothing. Describing comparative advantage without linking it to the global allocation of resources earns at most 1 mark." }],
  [`${U}.s014`, { modelAnswer: "Economic growth is an increase in an economy's real output, while economic development is the broader improvement in living standards and well-being. In China, rapid growth — real GDP grew 5.0% in 2024 after decades of very high growth — has funded development: since reform began, more than 800 million people have been lifted out of poverty, and life expectancy and literacy have risen sharply. In the short run, growth raises incomes and provides the resources to break poverty cycles. But growth does not automatically produce development: China's growth has been concentrated in coastal, export-oriented industries, leaving large rural–urban and regional gaps, and industrialisation has caused serious environmental damage that reduces quality of life. In the long run, development supports growth: investment in health, education and institutions builds the human capital and structural change on which sustained growth depends. The two are therefore mutually reinforcing but not identical.", rubric: ["1. Defines economic growth and economic development and states that they are related but distinct.", "2. Explains how growth can promote development (growth provides resources to break poverty cycles and fund health, education and infrastructure), with reference to the named economy.", "3. Explains how development supports long-run growth (development builds human capital and the structural change on which sustained growth depends).", "4. Analyses the relationship in both the short run and the long run (short-run growth may not immediately improve development; long-run development sustains growth).", "5. Integrates contemporary information about the named economy (e.g. China's growth rate and poverty-reduction record)."], notes: "Any economy other than Australia is acceptable; the rubric does not require a specific one. A correct answer must name the economy, distinguish growth from development, and analyse the two-way relationship. Growth data alone, without linking it to development, earns at most 2 marks. Treating growth and development as the same thing earns nothing." }],
  [`${U}.s015`, { modelAnswer: "A quota is a quantitative restriction on the volume of imports, limiting how much of a good can be imported into a country. In contrast, local content rules require that a minimum percentage of a finished good's inputs be sourced from domestic producers.", rubric: ["1. States that a quota is a quantitative restriction on the volume of imports.", "2. States that local content rules require a minimum percentage of a finished good to be sourced from domestic inputs, using a term of distinction (e.g. whereas, however)."], notes: "Both terms must be correctly defined and distinguished for 2 marks; defining one correctly earns 1 mark. The distinction is that a quota limits the quantity of imports, while local content rules mandate a minimum share of domestic content in production." }],
  [`${U}.s016`, { modelAnswer: "First, free trade allows countries to specialise according to their comparative advantage, leading to a more efficient allocation of resources and increased production. Second, it gives consumers access to a wider range of goods and services at lower prices, raising real incomes and living standards.", rubric: ["1. Outlines one benefit of free trade (e.g. specialisation and better resource allocation, increased production, lower prices and more choice, greater international competitiveness, or higher living standards).", "2. Outlines a second, different benefit of free trade from the same list."], notes: "The two benefits must be different. Naming free trade without a benefit, or giving two versions of the same benefit, earns at most 1 mark." }],
  [`${U}.s017`, { modelAnswer: "Recent changes in the international business cycle include the slowdown in global growth from 3.6% in 2018 to 2.87% in 2019, the COVID-19 recession of 2020 (global growth −3.06%, the worst since the Great Depression), and the recovery of 6.1% in 2021. For Vietnam, an export-oriented developing economy, these changes had a direct impact on growth: its growth fell from 7.2% in 2018 and 7.15% in 2019 to 2.9% in 2020, as lockdowns disrupted global supply chains and reduced demand for its exports, and to 2.6% in 2021, before recovering to about 7.5% in 2022 as global demand and foreign investment returned. Because exports are the main source of Vietnam's growth, the international cycle transmits to its economy through trade: weaker global demand reduces its exports, while a global recovery boosts them.", rubric: ["1. Identifies recent changes in the international business cycle (e.g. the 2019 slowdown, the 2020 COVID recession, the 2021 recovery).", "2. Names an economy other than Australia and explains how the cycle's changes affected its economic growth.", "3. Provides specific data on the other economy's growth (e.g. Vietnam's growth falling from 7.2% in 2018 to 2.9% in 2020).", "4. Explains the transmission mechanism linking the international cycle to the economy's growth (e.g. trade dependence: weaker global demand reduces exports, the main source of growth)."], notes: "Any economy other than Australia is acceptable; the rubric does not require a specific one. The question is about the international business cycle, not just COVID: answers should identify the cycle's phases (slowdown, recession, recovery) and link them to the economy's growth with data. Naming an economy without linking the cycle to its growth earns at most 1 mark.\nAccept any recent phase of the international cycle with data, not only 2019–2022: a student in 2027 may well use the 2023–2025 slowdown, the 2025 rise in US tariffs and trade tensions, or the IMF's latest growth estimates. The Vietnam figures in the model answer are an example only." }],
  [`${U}.s018`, { modelAnswer: "Globalisation has increased total global wealth, but its benefits have not been shared equally. Wealth is far more concentrated than income: in 2021, individuals worth more than US$1 million made up just 1.1% of the world's population but held 45.8% of global wealth, while those worth less than US$10,000 made up 55% of the population but held only 1.3%. Geographically, wealth remains concentrated in advanced economies, and the benefits of globalisation have flowed unevenly to emerging and developing economies. Between countries, income inequality has fallen this century as large developing economies such as China and India have converged, but wealth inequality within countries has tended to rise.", rubric: ["1. Explains that globalisation has increased global wealth but its benefits are not shared equally between advanced, emerging and developing economies.", "2. Explains that wealth is more concentrated than income, supporting the point with data (e.g. the top 1.1% of the population holding 45.8% of global wealth in 2021).", "3. Explains the geographical imbalance in the distribution of wealth (wealth concentrated in advanced economies and regions).", "4. Explains a nuance of the effect (e.g. between-country inequality has fallen this century while within-country inequality has risen)."], notes: "The question is about the distribution of wealth, not income alone; answers that discuss only income earn at most partial marks. The 4-mark band requires supporting data. Stating that \"globalisation made inequality worse\" without explaining the mechanism or providing data earns at most 2 marks." }],
  [`${U}.s019`, { modelAnswer: "Gross World Product is the sum of the total output of goods and services produced by all economies in the world over a period of time, usually a year.", rubric: ["1. Defines Gross World Product as the sum of the total output of goods and services produced by all economies in the world over a period of time."], notes: "The definition must include the \"all economies in the world\" and \"over a period of time\" elements. Per the marker's comments, omitting the time period is the most common error and earns nothing." }],
  [`${U}.s020`, { modelAnswer: "TNCs contribute to globalisation by being the main source of foreign direct investment, channelling investment from developed to developing and emerging economies, and by spreading technology, transport and communication networks around the world.", rubric: ["1. Outlines one contribution of TNCs to globalisation (e.g. providing foreign direct investment, facilitating increased trade in goods and services, spreading technology and communication, or facilitating the international division of labour)."], notes: "Only one contribution is needed for the mark, and it must be a genuine contribution of TNCs to globalisation. Naming TNCs without a contribution, or giving a contribution that belongs to another agent, earns nothing. Per the marker's comments, keep the outline concise — it is only 1 mark." }],
  [`${U}.s021`, { modelAnswer: "In response to the COVID-induced global recession — a recent change in the international business cycle — the IMF established a Short-term Liquidity Line providing one-off, interest-free loans to developing and emerging economies, and released a US$650 billion relief package (a new issuance of Special Drawing Rights) to help countries vaccinate their populations and service their foreign debt. These measures addressed the downturn by providing liquidity and stabilising vulnerable economies, and the IMF also provided policy and technical advice to member countries on tackling the high global inflation that followed.", rubric: ["1. Identifies a recent change in the international business cycle (e.g. the COVID downturn and global recession, rising public debt, supply-chain constraints, or the post-COVID surge in global inflation).", "2. Names ONE international organisation and outlines how it responded to that change (e.g. IMF short-term liquidity line and US$650 billion SDR relief package; World Bank vaccine and debt-relief funding; WTO trade-facilitation measures).", "3. Explains the cause-and-effect link — how the organisation's response addressed the change (e.g. provided liquidity and stabilised crisis-hit and heavily indebted economies during the downturn)."], notes: "The response must explain causes and effects, not just describe the organisation's general role (the marker's comment says describing the organisation rather than the causes/effects of its response cost students at least 1 mark). Recent changes in the IBC should be within the last ten years, preferably five. The G20 is a government economic forum, not one of the international organisations the syllabus treats here (WTO, IMF, World Bank, UN, OECD), and does not earn the mark." }],
  [`${U}.s022`, { modelAnswer: "In Vietnam, globalisation — pursued through Doi Moi reforms, trade and investment policies and integration into global manufacturing supply chains — has raised incomes but distributed the gains unevenly, and has improved quality of life for many while creating new costs. On income distribution, greater integration raised demand for labour in export manufacturing and tourism, increasing wages and attracting workers from rural areas, so absolute poverty fell and incomes at the bottom of the distribution rose (average income of the bottom 20% grew strongly). Against this, globalisation widened wage dispersion between rural and urban workers and between formal- and informal-economy workers, and rural and informal workers often earn well below the rising minimum wage, so inequality of income and wealth increased even as average incomes rose. On quality of life, integration into global markets and FTAs expanded consumers' access to goods and services, and the government's infrastructure, education and health spending (partly to attract transnational corporations) improved access to transport, education and health care. However, rapid export-led growth brought environmental degradation, urban overcrowding and a deepening digital divide between urban and rural workers, and minority groups such as the Hmong have not shared in the gains.", rubric: ["1. Names an economy other than Australia and explains how globalisation (trade, investment, TNCs, migration) has influenced its income and quality of life.", "2. Identifies a positive impact on the distribution of income (e.g. higher wages and employment in export industries, falling poverty, rising incomes at the bottom of the distribution) with an example or data.", "3. Identifies a negative impact on the distribution of income (e.g. wage dispersion between rural/urban or formal/informal workers, widening income and wealth inequality) with an example.", "4. Identifies a positive impact on quality of life (e.g. better access to goods and services, education, health and infrastructure) with an example.", "5. Identifies a negative impact on quality of life (e.g. environmental damage, urban overcrowding, a deepening digital divide) and overall discusses points for and against."], notes: "\"Discuss\" requires points for and against — the 5-mark band needs comprehensive points on both the distribution of income and quality of life, with integrated examples, data or trends. Any economy other than Australia is acceptable; the rubric does not require Vietnam. Answers that cover income OR quality of life only, or only one side of the argument, cap at 4 or 3 marks respectively. Rural–urban wage dispersion, informal workers and minorities missing out, and the environmental cost are the negative points markers expect to see." }],
  [`${U}.s023`, { modelAnswer: "Country X is an emerging economy.", rubric: ["1. Correctly identifies the type of economy for Country X (an emerging economy)."], notes: "Emerging economies have moderate income per capita and growth rates with uneven development outcomes. Calling Country X \"developing\" is not accepted here — the school's answer is \"emerging economy\"; saying \"advanced economy\" or \"developed economy\" earns nothing because its GNI per capita (≈$8,068) and HDI (0.61) are far below advanced-economy levels." }],
  [`${U}.s024`, { modelAnswer: "The HDI measures health (life expectancy) and education (mean and expected years of schooling) as well as income. Country Y's government has redistributed income more effectively towards spending on health and education, the other two dimensions of the HDI, leading to a higher life expectancy at birth and higher mean years of schooling, so Y's HDI score is higher even though its GNI per capita ($7,654) is below Country X's ($8,068).", rubric: ["1. Recognises that the HDI is made up of more than income — health and education as well as income — and links Country Y's higher score to those dimensions.", "2. Explains how Country Y achieves the higher score despite lower income (e.g. a more effective tax-transfer system or superior medical/education system → higher life expectancy and years of schooling)."], notes: "The key is that a country can rank higher on development than on income because development is multi-dimensional. Acceptable mechanisms: more effective tax-transfer system, superior medical and/or education system, higher spending on health and education. An answer that just says \"Y has a higher HDI\" without explaining why, or one that uses income only, earns at most 1 mark." }],
  [`${U}.s025`, { modelAnswer: "Country Z is potentially the most vulnerable to a global recession. Its total trade as a proportion of GDP is the highest of the three: exports of $22bn plus imports of $26bn is $48bn, which is 62.3% of its GDP of $77bn, compared with 44.0% for Country Y (125⁄284) and 45.5% for Country X (110⁄242). Country Z is therefore the most integrated into the global economy and the most susceptible to a downturn in the international business cycle, because a global recession that reduces world trade would cut its exports and national income by proportionally more than for the less open economies.", rubric: ["1. Correctly identifies the country that is potentially most vulnerable (Country Z).", "2. Explains that Country Z's trade intensity (total trade as a percentage of GDP, 62.3%) is the highest of the three economies.", "3. Justifies the choice by linking the high trade intensity to greater integration and therefore greater susceptibility to a downturn in the international business cycle."], notes: "The school's marking guideline gives Country Z's trade intensity as 62.3% and notes Country X is the only country that cannot be accepted as a valid answer. Answers should show the calculation of trade-to-GDP (or at least compare openness). A justification that simply names the largest trade values without relating them to GDP is too weak for full marks." }],
  [`${U}.s026`, { modelAnswer: "In the short run the quota maintains employment in the protected domestic industry, but over time it is likely to reduce economy-wide employment. Firms sheltered from international competition face lower competitive pressures, which drives less innovation and results in stagnating technical efficiency and a reduction in the allocative efficiency of resource use, as resources are attracted from more efficient industries into the less efficient protected industry. Production in those other industries then declines because of shortages and higher prices for inputs. Economic growth falls below the output potential of the economy, creating less employment overall than there would have been without the import quota.", rubric: ["1. Outlines the short-run effect: the quota protects (maintains) employment in the domestic industry.", "2. Explains that the quota reduces competitive pressure on protected firms, slowing innovation and reducing technical and allocative efficiency.", "3. Explains the economy-wide consequence over time: resources move into the less efficient protected industry, other industries contract, growth falls below potential, and overall employment falls."], notes: "The question asks why protection leads to an overall decrease in employment over time, so the answer must move from the protected industry to the wider economy. The marker's sample answer traces: less competition → less innovation → stagnating technical efficiency → lower allocative efficiency → resources drawn to the inefficient industry → other industries decline → growth below potential → less employment. An answer that only says \"the quota saves jobs\" or only describes what a quota is earns at most 1 mark." }],
  [`${U}.s027`, { modelAnswer: "The tariff raises the domestic price from the world price of $20 to $40, so domestic production increases from 120 units to 140 units (an increase of 20 units). On the diagram, indicate this increase in the quantity supplied between the $20 price line and the $40 price line, along the domestic supply curve.", rubric: ["1. Correctly identifies the change in domestic production: domestic output rises (from about 120 units at the world price of $20 to about 140 units at the with-tariff price of $40)."], notes: "The mark requires the direction and the amount of the change to be identified. On the diagram, domestic production is read off the domestic supply curve at each price: supply rises from Q1 (at $20) to Q2 (at $40). Indicating only \"domestic production\" without the increase, or simply shading an area, earns nothing." }],
  [`${U}.s028`, { modelAnswer: "A quota of 30 units. With a $10 tariff the domestic price rises from the $20 world price to $30. At $30, domestic supply is 130 units and domestic demand is 160 units, so imports are 160 − 130 = 30 units. A quota set at 30 units therefore has the same effect on domestic output as the $10 tariff.", rubric: ["1. Correctly identifies the import quota (30 units) that has the same effect on domestic output as a $10 tariff."], notes: "The quota equals the volume of imports at the price the $10 tariff produces (P = $30): imports = domestic demand − domestic supply at that price. Expressing the answer in units is required (the school's own \"areas for improvement\" note says students must state units). Answers of \"30\" without units, or a different quantity, earn nothing." }],
  [`${U}.s029`, { modelAnswer: "A government may protect an infant industry: a newly established domestic industry is temporarily sheltered from established overseas competitors until it grows large enough to achieve economies of scale, lower its costs and become internationally competitive without assistance.", rubric: ["1. Outlines one reason for protection (e.g. protecting an infant industry, protecting domestic employment, preventing dumping, or national defence/self-sufficiency).", "2. Gives detail that contributes the outline (e.g. that the infant industry needs temporary shelter until it achieves scale and can compete; or that the tariff saves jobs in an import-competing industry in the short run)."], notes: "\"Outline\" requires a sketch in general terms with some detail, not just a one-word name — naming \"infant industry\" alone earns 1 mark, outlining how the reason operates earns 2. Any one of the syllabus reasons (infant industry, domestic employment, dumping, defence) is acceptable; the reason must be a genuine reason for protection." }],
  [`${U}.s030`, { modelAnswer: "Tariffs tax imports, raising the domestic price above the world price so that the quantity imported falls and domestic production increases, protecting domestic industries and jobs; they also generate government revenue equal to the tariff times the quantity imported, which can fund microeconomic reform that helps infant industries become more efficient. However, tariffs increase prices for consumers, push resources into inefficient import-competing industries, and generally reduce economy-wide efficiency and living standards. Quotas limit the physical quantity of a good that may be imported; they also push the domestic price up and encourage domestic production, but because no tax is collected the higher price does not become government revenue — the gains go to importers and foreign producers. Subsidies enable domestic producers to supply more at every price, reducing the quantity of imports needed without raising the price consumers pay; but they are a direct cost to the government budget and can distort resource allocation, and in the long run subsidies can reduce GDP as resources stay in industries that would not survive on their own. Overall, the different protectionist policies all shelter domestic industries and can protect employment and output in the short run, but each imposes costs — higher consumer prices, lost government revenue or budget spending, weaker competitive pressure, and slower structural change — so their net effect on the domestic economy over time is negative.", rubric: ["1. Outlines that a tariff raises the domestic price above the world price, reducing imports and increasing domestic production.", "2. Explains a point for a tariff: it protects domestic industry and employment and raises government revenue (tariff × quantity imported), which can fund microeconomic reform.", "3. Explains a point against a tariff: consumers pay higher prices and resources move into inefficient protected industries, reducing welfare.", "4. Outlines the effect of a quota: it limits imports, pushes up the domestic price and encourages domestic production, but generates no government revenue (gains go to importers/foreign producers).", "5. Outlines the effect of a subsidy: domestic producers supply more at every price so imports fall, without raising consumer prices, at a direct cost to the government budget.", "6. Discusses the policies together — protecting jobs/output in the short run but weakening competition, efficiency and structural change so the long-run effect on the domestic economy is negative."], notes: "\"Discuss\" requires points for and against a range of protectionist policies — the top band (5–6) needs a clear and comprehensive understanding of points for and against, over several different policies. The school's own marking notes that students needed to explore a range of policies (tariffs, quotas, subsidies), link cause and effect, and not drift into discussing reductions in protection. Comparing the policies (tariff raises revenue, quota does not, subsidy keeps consumer prices lower but costs the budget) is what lifts an answer above 4 marks. Naming one policy only, or describing protection without effects, caps at 2–3 marks." }],
  [`${U}.s031`, { modelAnswer: "Economic development has worsened, because the Human Development Index has fallen from 0.784 to 0.692.", rubric: ["1. Correctly identifies that economic development has worsened (because the HDI has fallen)."], notes: "The HDI ranges from 0 to 1, and higher values mean better development outcomes, so a fall from 0.784 to 0.692 is a worsening of economic development. Saying \"improved\" gets nothing; the mark requires the direction of the change." }],
  [`${U}.s032`, { modelAnswer: "Gross World Product is the total market value of all final goods and services produced by all economies in the world in a given period, usually a year — the \"GDP of the world\". It is measured at current prices or, for comparing real growth, adjusted for purchasing power (PPP) so that the total output of the global economy can be compared over time.", rubric: ["1. Defines Gross World Product as the total market value of all final goods and services produced by all economies in the world over a period, usually a year.", "2. Gives an accurate detail of measurement or use (e.g. measured at current prices or PPP-adjusted; it measures the size of total world output)."], notes: "The definition must be the world's total output, not one country's GDP and not world trade. Acceptable detail: measured at current prices (nominal, US$) or adjusted for purchasing power; used as the headline \"world growth\" figure; growth of GWP ≠ every country growing. Omitting \"over a period of time\" is the most common error and loses the mark." }],
  [`${U}.s033`, { modelAnswer: "Economic growth is usually measured using GDP or GDP per capita and looks at the monetary value of the goods and services produced by an economy over time. Economic development is a much broader measure of human wellbeing: it is mainly measured by the Human Development Index, which covers life expectancy at birth, levels of educational attainment and GNI per capita. The main difference is the scope — economic growth measures output, while economic development measures the wider quality of people's lives.", rubric: ["1. States that economic growth is the increase in an economy's output, measured as real GDP or GDP per capita.", "2. States that economic development is broader, measuring human wellbeing (e.g. via the HDI — health, education and income) and uses a term of distinction between the two."], notes: "Both must be described with their different measures or scope for 2 marks; describing only one earns 1 mark. \"Economic growth is GDP\" with no content, or treating the two as the same, is the marker's flagged weak answer. Development goes beyond income to health, education and living standards." }],
  [`${U}.s034`, { modelAnswer: "China has used a range of economic policies to raise economic development. Its Open Door policy (from 1978) established Special Economic Zones on the coast, with tax concessions and reduced red tape, which attracted foreign direct investment, exports and technology; joining the WTO in 2001 and cutting tariffs integrated China into world markets and expanded its manufacturing export base. These policies raised growth and then development: since reform began, more than 800 million people have been lifted out of poverty, life expectancy and literacy have risen sharply, and China's HDI has risen into the high band even though distribution of the gains has been uneven. The policies worked by linking trade and investment to rising wages, employment and government revenue, which funded education, health and infrastructure, and by transferring technology and skills through TNCs.", rubric: ["1. Names an economy other than Australia and identifies an economic policy it has used to promote development (e.g. Chinese SEZs/Open Door policy, WTO accession, tariff reduction, infrastructure spending).", "2. Describes the key features of the policy (how it works — e.g. tax concessions and deregulation attract FDI and exports; WTO membership lowers trade barriers).", "3. Explains the mechanism linking the policy to economic development (e.g. higher wages and employment, government revenue spent on education, health and infrastructure, technology transfer).", "4. Provides statistical evidence of improved development (e.g. 800+ million people lifted out of poverty since reform; rising HDI, life expectancy or literacy).", "5. Examines more than one strategy or evaluates the outcome (e.g. notes growth has been uneven, with inequality and environmental costs)."], notes: "Any economy other than Australia is acceptable; the rubric does not require China. The marker's note says students must link the economic policy to improved development, using statistical evidence (most likely changes in HDI); writing about a development program that is not an economic policy misses the question. Stronger answers give at least two policies with their outcomes." }],
  [`${U}.s035`, { modelAnswer: "The WTO promotes globalisation by overseeing trade negotiations that reduce tariffs and other protection among its (164) member nations, for example running the Uruguay Round and administering agreements such as GATT, TRIPS and GATS, so that trade flows grow and economies integrate.", rubric: ["1. Outlines one specific role of the WTO that promotes globalisation (e.g. negotiating and overseeing the reduction of tariffs and other protection among members, resolving trade disputes, or administering multilateral trade agreements such as GATT/TRIPS/GATS)."], notes: "The role must be the WTO's own and must promote globalisation through reduced barriers to trade. Simply saying \"the WTO encourages free trade\" is too vague for the mark (the marker's comment). Swapping in another organisation's role (e.g. the IMF's lending) earns nothing; the WTO does not negotiate bilateral FTAs." }],
  [`${U}.s036`, { modelAnswer: "One global factor is the structure of the global trading system, which often works against developing nations' comparative advantages: developed economies maintain high agricultural protection and the Doha Round of trade liberalisation stalled, so developing countries have limited access to rich-country markets and their export earnings stay low, widening income differences. A second global factor is the global financial system and access to foreign capital: developing nations are often judged too risky to attract FDI and TNC investment, and those that rely on portfolio investment and foreign debt face capital flight and debt-servicing burdens that constrain growth, while advanced economies attract large capital inflows — so the gap between nations widens.", rubric: ["1. Identifies and explains the first global factor (e.g. the global trade system and trade blocs/FTAs working against developing nations, WTO failure/Doha stalemate, agricultural protection).", "2. Clearly explains how that factor accounts for differences between nations (e.g. reduced export access and earnings for developing nations).", "3. Identifies and explains the second global factor (e.g. the global financial system: FDI and TNCs avoiding risky developing nations, reliance on portfolio investment and foreign debt, or the failure of foreign aid commitments).", "4. Clearly explains how that factor accounts for differences between nations (e.g. capital flight, debt constraints and limited investment keep developing economies poor)."], notes: "\"Explain\" requires the mechanism, not just a list — the 4-mark criteria rewards clearly explaining TWO global factors. The marker's comment says responses that focused only on domestic factors (natural resources, weak institutions) lost marks unless linked to attracting FDI. The factors must be global (trade system, financial system, international division of labour, aid), not domestic." }],
  [`${U}.s037`, { modelAnswer: "China's strategies to promote trade and investment include the Open Door policy and Special Economic Zones (1978 onwards), with tax concessions and deregulation that attracted foreign direct investment and built an export-based manufacturing base, and joining the WTO in 2001, which reduced tariffs and gave Chinese exports secure access to world markets. Complementing these are large infrastructure programs and policies such as the Western Development Plan and Belt and Road Initiative. These strategies have been highly effective: China's trade-to-GDP ratio rose sharply, it became the world's biggest exporter, and rapid growth funded dramatic development — more than 800 million people lifted out of poverty and a much higher HDI. The strategies also carried costs: income inequality and regional disparities grew, environmental damage increased, and heavy reliance on exports made growth vulnerable to swings in the international business cycle, so the strategies promoted growth effectively but produced uneven development.", rubric: ["1. Names an economy other than Australia and identifies strategies used to promote trade and investment (e.g. SEZs/Open Door policy, tax concessions, WTO accession, reducing tariffs, infrastructure such as the Western Development Plan or Belt and Road).", "2. Outlines the key features of the strategies and how they work (e.g. tax concessions and deregulation attract FDI and exports; WTO membership lowers trade barriers and secures market access).", "3. Explains the outcomes of the strategies for trade and investment (e.g. higher trade-to-GDP ratio, large FDI inflows, growth of the manufacturing export base).", "4. Links the outcomes to economic growth or development with evidence (e.g. 800+ million people lifted out of poverty since reform; rising HDI).", "5. Evaluates the strategies — makes a judgement, e.g. noting the costs and trade-offs (income inequality, regional disparities, environmental damage, export dependence) as well as the gains."], notes: "\"Evaluate\" needs a judgement with points for and against. Any economy other than Australia is acceptable; the school's resources use China. Answers that only describe strategies without outcomes, or lack evaluation, cap at 3 marks. Accept Chile, Vietnam, India, South Korea or others with economy-specific strategies and evidence." }],
  [`${U}.s038`, { modelAnswer: "Two distinguishing characteristics of an advanced economy are a high income per capita (high GDP or GNI per capita and standard of living compared with developing and emerging economies) and a diversified industrial base, with the economy driven by a large and productive service sector and advanced manufacturing rather than reliance on primary commodities and low-cost manufacturing.", rubric: ["1. Identifies one distinguishing characteristic of an advanced economy (e.g. high income per capita, a large and productive service sector, advanced manufacturing, a high HDI, low birth rates, or sustainable growth).", "2. Identifies a second, different distinguishing characteristic from the same list."], notes: "Two distinct features are required for 2 marks. The characteristics must set advanced economies apart from developing and emerging economies — income level and the structure of the industrial base are the two the school marks. Listing one feature twice (e.g. \"high income\" and \"high GDP per capita\") earns only 1 mark." }],
  [`${U}.s039`, { modelAnswer: "Free trade allows countries to specialise according to their comparative advantage — producing the goods and services they can make at the lowest opportunity cost — and to trade their surplus output for goods they produce less efficiently. This specialisation leads to a more efficient allocation of resources globally, higher total world output, and increased consumer choice at lower prices, which raises economic welfare for the countries that trade.", rubric: ["1. States the economic rationale in clear terms: free trade lets countries specialise according to comparative advantage (lower opportunity cost), improving resource allocation and raising output.", "2. Links the rationale to the gains from trade or increased welfare (e.g. higher total world output, more choice and lower prices for consumers, higher GWP and living standards)."], notes: "For 2 marks the answer must mention comparative advantage or explain the mechanism and end with the gain (higher output, welfare, living standards). A general answer like \"it increases efficiency\" or \"it benefits all countries\" without comparative advantage or a final gain earns 1 mark. Absence of the final \"point\" (higher GWP, living standards) was the marker's main reason for losing the mark." }],
  [`${U}.s040`, { modelAnswer: "Subsidies are payments from the government to domestic producers that lower their production costs, allowing them to sell goods at lower prices (or to produce more at the world price). The lower prices give domestic producers an artificial competitive advantage over imports, making local goods more attractive and discouraging imports, which protects domestic producers from foreign competition.", rubric: ["1. States that subsidies are government payments to domestic producers that lower their production costs, so domestic goods can be sold at lower prices.", "2. Explains that this creates an artificial competitive advantage over imports, which protects domestic producers from foreign competition."], notes: "The explanation of HOW a subsidy protects is needed for 2 marks: the lower production cost → lower price → artificial advantage over imported goods. The marker's comment says marks were lost by not saying how (lower production costs) and by not referencing overseas producers/competition. \"Subsidies help local producers\" alone earns 1 mark." }],
  [`${U}.s041`, { modelAnswer: "International labour migration affects advanced, emerging and developing economies differently. Advanced economies generally gain: skilled migrants from developing nations create a \"brain gain\", filling skill shortages, raising productivity and innovation and supporting an upward wealth cycle, though they may face social integration challenges. Emerging economies receive lower-skilled migrant labour from developing nations, boosting output in labour-intensive industry and construction, but they can also lose skilled workers to advanced economies (a partial brain drain) and may later gain from return migration that brings skills and knowledge home. Developing economies face the most negative impact: brain drain removes their most talented and educated citizens, worsening skill shortages and slowing growth, while large numbers of low-skilled workers emigrate to emerging economies; however, remittances inflow foreign currency, raising household incomes, reducing poverty and stimulating demand. On balance, migration is most beneficial to advanced economies, mixed for emerging economies, and a net drain on developing economies, even after counting remittances.", rubric: ["1. Assesses the impact on advanced economies (e.g. brain gain of skilled workers, filling skill shortages, raising productivity and innovation, with possible social integration challenges).", "2. Assesses the impact on emerging economies (e.g. receiving lower-skilled labour for industry and construction, partial brain drain, and skills/knowledge gains from return migration).", "3. Assesses the impact on developing economies (e.g. brain drain worsening skill shortages and slowing growth; large outflows of low-skilled workers).", "4. Weighs the overall effect with a judgement (e.g. remittances help developing economies but do not fully offset brain drain; migration benefits are uneven across the three types)."], notes: "The 4-mark band requires judgement across advanced, emerging and developing economies, integrating positive and negative effects with clear cause-and-effect links and economic terminology. Covering only one or two economy types caps out at 2–3 marks. Remittances alone, or brain drain alone, earns at most 1–2 marks because the question asks for an assessment across types." }],
  [`${U}.s042`, { modelAnswer: "A subsidy leads domestic producers to supply a greater quantity of the good, because the government payment lowers their costs of production and makes producing at the world price profitable; this increases domestic output while reducing the volume of imports. It also imposes a direct cost on the government's budget.", rubric: ["1. Outlines one economic effect of a subsidy (e.g. domestic producers supply a greater quantity; it leads to a misallocation of resources; it imposes a direct cost on the government's budget).", "2. Gives some detail that constitutes the outline (e.g. the payment lowers production costs so domestic output rises and imports fall)."], notes: "Only one effect is required for the mark structure, but the top mark needs it outlined (a sketch in general terms with some content). The school's acceptable effects are: domestic producers supply a greater quantity; it leads to a misallocation of resources; direct costs on the government's budget. Naming \"a subsidy\" without an effect earns nothing." }],
  [`${U}.s043`, { modelAnswer: "The World Bank has accelerated development and structural change in developing and transitioning economies by pursuing a free-market approach: it encourages fiscal responsibility and funds sustainable development through carbon trading funds, conservation and clean-water and sanitation initiatives, and spends on malaria treatment and HIV/AIDS programs. The IMF's roles include lending to countries to solve current-account-deficit problems (acting as the international lender of last resort), implementing structural adjustment policies such as deregulation and privatisation, maintaining international financial stability in times of crisis, and encouraging the free movement of finance and capital throughout world markets. These activities bring more economic activity to developing countries and boost their economic growth and development.", rubric: ["1. Describes the World Bank's role in development (e.g. funding and technical support for development and structural change, free-market/fiscal-responsibility programs, health and clean-water initiatives).", "2. Describes the IMF's role (e.g. lending to countries with current-account difficulties as lender of last resort, structural adjustment, promoting financial stability in crisis).", "3. Describes at least one of the organisations' mechanisms in detail (e.g. structural adjustment policies such as deregulation and privatisation; crisis lending that stabilises economies).", "4. Explains how these activities accelerate global economic development (e.g. more economic activity in developing countries → higher growth and development)."], notes: "The school's 4-mark band requires a comprehensive understanding of the differences between the IMF and the World Bank — getting their roles swapped caps the answer. Both organisations must appear with correct roles; describing development outcomes without the mechanism, or describing only one organisation, earns at most 2–3 marks. Mentioning the WTO's or OECD's roles earns nothing for those points." }],
  [`${U}.s044`, { modelAnswer: "Imports at the world price of $20 are 200 units (domestic demand 300 units minus domestic supply 100 units).", rubric: ["1. Correctly identifies the quantity of imports at the world price of $20 (200 units; imports = Qd − Qs = 300 − 100)."], notes: "The mark requires the calculation or the final quantity. Imports are the gap between domestic demand and domestic supply at the world price (300 − 100 = 200). Answering \"300\" (demand) or \"100\" (supply) earns nothing; the answer should state units." }],
  [`${U}.s045`, { modelAnswer: "Domestic producer revenue is $8,000: domestic production is 200 units, each receiving the $20 world price ($4,000) plus the $20 subsidy ($4,000), so 200 × $20 + 200 × $20 = $8,000.", rubric: ["1. Correctly calculates domestic producer revenue after the $20 subsidy ($8,000, i.e. 200 units × ($20 world price + $20 subsidy) = $8,000)."], notes: "The school's solution counts both the market revenue (200 × 20) and the subsidy revenue (200 × 20) as part of domestic producer revenue, giving $8,000. Omitting the subsidy component gives $4,000, which is not the school's answer. The answer should state dollars." }],
  [`${U}.s046`, { modelAnswer: "The International Monetary Fund promotes stability in the global economy by monitoring the world's monetary system and the economic policies of its members, and by lending temporary financial assistance to member countries facing balance-of-payments crises. This stabilises troubled economies and restores investor confidence, limiting the spread of financial crises across borders and supporting the smooth operation of international trade and payments.", rubric: ["1. Names one international organisation and identifies its role (e.g. IMF surveillance and lending; World Bank development loans; WTO trade-rule administration and dispute settlement; OECD policy research; UN development goals).", "2. Describes how the role works (e.g. the IMF lends with conditions to countries in balance-of-payments difficulty; the World Bank funds specific development projects; the WTO negotiates and enforces trade rules).", "3. Explains how the organisation's role influences the global economy (e.g. crisis lending restores confidence and stops contagion; funded projects raise productivity and living standards; lower trade barriers expand world trade and growth)."], notes: "The organisation must be a genuine international organisation — the school notes G7/G20 is an economic forum, not an international organisation, and does not qualify. The role must be the correct one for the organisation (swapping the IMF's and World Bank's roles caps the answer at 1 mark). \"Describe\" requires how it works and its global influence, not just naming the organisation." }],
  [`${U}.s047`, { modelAnswer: "Differences between emerging and advanced economies come from their access to global finance, trade, technology and their own capacity to turn those into growth. Advanced economies are deeply integrated into the global financial system and have easy access to credit, while emerging economies attract less foreign direct investment (traditionally concentrated between developed countries) and rely more on short-term portfolio flows, leaving them exposed to capital flight. In trade, developed countries maintain protected agricultural industries and dominate established trading blocs and WTO negotiations, so emerging economies face barriers to the export markets where their comparative advantage lies. Technology is adopted faster in advanced economies because infrastructure is better, and their governments raise education and health levels, while emerging economies may lack the political and economic institutions needed to convert global opportunities into sustained development. However, several emerging economies are industrialising faster than advanced economies, producing higher sustained growth rates, so the size of the gap is closing for the strongest performers.", rubric: ["1. Identifies a financial factor (e.g. depth of integration into the global financial system, credit availability, FDI flows, reliance on portfolio investment and capital-flight risk).", "2. Identifies a trade factor (e.g. agricultural protection in developed countries, established trading blocs and WTO power excluding emerging economies, corporate tax avoidance by TNCs).", "3. Identifies a technology or human-capital factor (e.g. faster technology adoption in developed countries due to better infrastructure; differences in education and health levels).", "4. Identifies an institutional/internal factor (e.g. quality of political and economic institutions, factor endowments and resource allocation, degree of industrialisation).", "5. Analyses how these factors produce the difference between advanced and emerging economies, with some judgement (e.g. the gap persists for most, but rapidly industrialising emerging economies can narrow it)."], notes: "\"Analyse\" requires examining how the factors produce the difference, not just listing them. The school's answers include global financial integration, FDI concentration, the global trade system, tax avoidance of TNCs, little global aid, technology adoption, factor endowments, institutions, and education/health levels. Covering only emerging OR only advanced economies, or only listing factors without linking them to the difference, caps the answer at 2–3 marks." }],
  [`${U}.s048`, { modelAnswer: "Reducing the subsidy lowers the quantity of domestic supply and increases the quantity of imports, but it does not change the market price, which stays at the world price. The increase in imports reduces aggregate demand because domestic production falls and more spending leaks to imports, so gross domestic product falls in the economy.", rubric: ["1. Outlines the impact on domestic prices (the price is unchanged — it stays at the world price; only the quantity of domestic and imported supply changes).", "2. Outlines the impact on gross domestic product (GDP falls: higher imports and lower domestic production reduce aggregate demand and output)."], notes: "Both elements must be outlined for 2 marks; outlining only the price effect or only the GDP effect earns 1 mark. The school's answer notes the subsidy reduction does not affect the market price because the price is set at the world price, but does reduce GDP via higher imports and lower aggregate demand." }],
  [`${U}.s049`, { modelAnswer: "The Human Development Index combines GNI per capita (PPP) with education and life expectancy at birth. A country can have a higher GNI per capita (PPP) than another but still have a lower HDI if it performs worse on the other two components of the index — lower educational attainment and lower life expectancy — because the HDI is an average of all three dimensions, not income alone.", rubric: ["1. Identifies that the HDI includes more than income: it combines GNI per capita (PPP) with education and life expectancy at birth.", "2. Explains the cause and effect: a country with higher GNI per capita can have a lower HDI when its education and life-expectancy outcomes are lower than the other country's."], notes: "The answer must provide cause and effect earning 2 marks: higher income alone does not determine HDI because the index averages income, education and health. Mentioning that income is only one of three HDI dimensions, with the education and health shortfall explaining the lower HDI, is the mechanism markers want." }],
  [`${U}.s050`, { modelAnswer: "In China, globalisation — through increased trade, foreign investment by TNCs, technology transfer and urbanisation — transformed the economy, delivering rapid growth, higher incomes, employment and development, with hundreds of millions lifted out of poverty since reform began; but it also brought costs, including regional and income inequality, and significant environmental damage. China adopted environmental policies including renewable-energy expansion, emissions trading (a national ETS launched in 2021) and pollution limits in industrial cities. These policies have been partially effective: China is now the world's largest producer of solar and wind energy and its air-quality measures cut urban pollution sharply, but total carbon dioxide emissions are still rising and coal still dominates the energy mix, so the policies have slowed but not reversed environmental degradation. Overall, globalisation has had a strongly positive influence on China's economy but a negative effect on its environment, and its environmental policies are improving but not yet fully effective because growth and energy demand are still expanding faster than the transition to clean energy.", rubric: ["1. Names an economy other than Australia and analyses how globalisation has influenced its economy (e.g. growth, quality of life, trade, investment, TNCs, technology, migration).", "2. Identifies a positive economic influence of globalisation (e.g. faster growth, rising incomes and employment, technology transfer) with evidence.", "3. Identifies a cost of globalisation for the economy (e.g. income inequality, regional disparities, structural change) with evidence.", "4. Describes more than one environmental-sustainability policy of the country (e.g. renewable energy targets, emissions trading, pollution-control measures).", "5. Analyses the effectiveness of those policies (e.g. air-quality improvements, rising renewables share vs continuing emissions growth and coal dependence).", "6. Makes an overall assessment or judgement linking the two legs of the question (the economy gained from globalisation while the environment lost, and the policies are improving but only partially effective)."], notes: "The question has two legs, and the 6-mark band needs a well-informed judgement on BOTH the influence of globalisation on the economy and the effectiveness of environmental-sustainability policies. Any economy other than Australia is acceptable; the rubric does not require China. A judgement on only one leg earns at most 3–4 marks; listing policies without judging their effectiveness, or describing globalisation without environmental policies, caps at 4 marks." }],
  [`${U}.s051`, { modelAnswer: "Economic growth is the increase in an economy's total output of goods and services, measured by real GDP or real GDP per capita. Economic development is broader: it is the improvement in living standards and well-being, covering not only income but quality-of-life dimensions such as education (years of schooling) and health (life expectancy). Growth can occur without development if the extra output does not improve people's lives, whereas development requires growth to be converted into better quality of life.", rubric: ["1. Defines economic growth (an increase in the economy's total output of goods and services, real GDP or real GDP per capita).", "2. Distinguishes it from economic development, defining development as involving quality-of-life improvements (e.g. years of schooling, life expectancy) beyond income."], notes: "The two terms must be set against each other, not just defined separately. Defining both correctly without the distinction at which development goes beyond income caps at 1 mark. \"Growth equals development\", or naming HDI without explaining that it measures quality of life, earns at most 1 mark." }],
  [`${U}.s052`, { modelAnswer: "One domestic reason is the quantity and quality of human capital: countries with higher education levels, healthier workforces and a stronger entrepreneurial culture can attract and use capital and technology more productively, so their growth converts into rising living standards and HDI, while countries short of skilled labour develop more slowly. One global reason is how a nation is placed in the global trade system: economies that are integrated into the world economy through the WTO rules, trade blocs and global financial architecture receive more trade, investment, technology flows and aid, providing the capital and markets that raise development, whereas countries that are largely excluded from global trade and finance lack these opportunities and fall behind.", rubric: ["1. Explains ONE domestic reason for differences in economic development between nations (e.g. natural endowments, labour supply and quality, access to capital and technology, entrepreneurial culture).", "2. Links the domestic reason to the development outcome (e.g. better education and skills raise productivity and convert growth into higher living standards/HDI).", "3. Explains ONE global reason for differences in economic development between nations (e.g. the global trade system/trade blocs/WTO, the global financial architecture, global technology flows, global aid and assistance).", "4. Links the global reason to the development outcome (e.g. integration into world trade and finance brings capital, markets and technology that raise development)."], notes: "Both a domestic AND a global reason are required for full marks; giving only one side caps the answer at 2 marks. The top band requires \"comprehensive understanding\": each reason explained with cause and effect, not just named. The rubric credits any valid domestic or global factor, not only the guideline's list (natural endowments, labour supply/quality, capital and technology, entrepreneurial culture; trade system, financial architecture, tech flows, aid)." }],
  [`${U}.s053`, { modelAnswer: "Globalisation has had a transformative impact on China. Trade flows and foreign investment allowed China to industrialise and specialise according to comparative advantage: exports of manufactures and inward FDI raised productivity and growth, and since reform began more than 800 million people have been lifted out of poverty, with the HDI rising from about 0.50 in 1990 to about 0.77, so economic development improved dramatically. However, the impact is not all positive: globalisation exposed China to the international business cycle, so shocks such as the 2008–09 global financial crisis and the 2020 COVID recession cut export demand and slowed growth, and rapid export-led industrialisation worsened air pollution and environmental degradation while contributing to income inequality between the fast-growing coastal regions and the interior. Overall, globalisation has raised China's growth, incomes and quality of life, but with environmental and distributional costs.", rubric: ["1. Names an economy other than Australia and defines or identifies the drivers of globalisation relevant to it (e.g. trade flows, financial flows, TNCs, technology).", "2. Analyses a positive impact of globalisation on the economy's growth and/or development (e.g. export-led industrialisation, FDI, technology transfer, rising incomes and HDI) with evidence.", "3. Analyses a cost or risk of globalisation for the economy (e.g. exposure to the international business cycle, environmental degradation, income inequality).", "4. Makes a judgement or overall analysis linking the drivers to the net impact on the chosen economy (e.g. strong gains in growth and development offset by environmental and distributional costs)."], notes: "Any economy other than Australia is acceptable; the rubric does not require China. \"Analyse\" requires examining how globalisation produces the effects, not just listing drivers or outcomes. The top band needs a comprehensive account covering the drivers and the impact on economic growth and/or development; answers covering only growth, or only costs, cap at 2–3 marks. China data (800+ million lifted out of poverty since reform; HDI from about 0.50 in 1990) is from 04-key-content.md." }],
  [`${U}.s054`, { modelAnswer: "Economic development is the multi-dimensional improvement in a country's living standards and well-being, measured by income and quality-of-life indicators such as the Human Development Index (life expectancy, education and GNI per capita). It is broader than economic growth because it captures whether increases in output actually improve people's lives.", rubric: ["1. Clearly states the meaning of economic development (improvement in living standards and well-being beyond income alone).", "2. Identifies factors relating to economic development (e.g. quality of life and the HDI, education, life expectancy, GDP per capita)."], notes: "The second mark rewards naming the quality-of-life indicators (HDI, education, life expectancy); examples were commonly used to gain the second mark in the school's marking. Confusing economic development with economic growth (an increase in real GDP) loses the top mark. Listing \"GDP per capita\" alone with no reference to living standards caps at 1 mark." }],
  [`${U}.s055`, { modelAnswer: "One domestic influence is a nation's education levels and labour-force skills. Globalisation spreads trade, technology and investment opportunities across nations, but a country's ability to convert them into development depends on domestic factors: countries with better education and skills can attract foreign investment and technology and compete in global markets, so they develop faster, while countries with weak education and low skills are less able to benefit from globalisation and fall further behind.", rubric: ["1. Identifies ONE domestic influence on development (e.g. natural resources, entrepreneurial culture, access to technology, labour laws and skills, education levels).", "2. Outlines how that domestic influence contributes to the differences in development between nations through the process of globalisation (e.g. skills and education determine which nations can absorb trade, investment and technology)."], notes: "The influence must be domestic — the school's marking rejects global factors (e.g. the world trade system) for this part. The second mark needs the link between the domestic influence and the differences in development under globalisation; naming the factor alone earns 1 mark." }],
  [`${U}.s056`, { modelAnswer: "Trade flows have promoted global growth by allowing countries to specialise according to comparative advantage. With trade liberalisation through GATT/WTO rounds and free trade agreements, production shifts to the economies that produce most efficiently, total world output rises, and countries are able to consume beyond their own production possibilities; trade also transfers technology and capital between nations, widening the diffusion of new ideas and raising productivity across the world. Financial flows have promoted global growth by moving savings from surplus to deficit countries: financial deregulation and the growth of global financial markets have allowed capital to flow to productive investment wherever the returns are highest, financing industrialisation in emerging economies and funding infrastructure and business expansion, while portfolio flows and foreign direct investment by TNCs tie national financial systems together. Together, greater trade and financial flows have deepened global interdependence, improved the international allocation of resources and driven the long-run expansion of world output and living standards.", rubric: ["1. Analyses how trade flows promote global growth (e.g. specialisation according to comparative advantage raises world output and allows consumption beyond the PPF).", "2. Analyses the mechanisms of trade growth in detail (e.g. trade liberalisation through GATT/WTO and FTAs, technology and capital transfer through trade, expansion of the international division of labour).", "3. Analyses how financial flows promote global growth (e.g. savings transferred from surplus to deficit countries finance productive investment).", "4. Analyses the mechanisms of financial-flow growth in detail (e.g. financial deregulation, global financial markets, FDI and portfolio flows, TNC investment).", "5. Links the two flows and shows their implications for world growth (e.g. deeper global interdependence, better global allocation of resources, faster industrialisation of emerging economies).", "6. Provides a comprehensive analysis with an overall judgement (e.g. the two flows together have been a principal driver of long-run world growth and rising living standards)."], notes: "The school's top band (5–6) requires clearly showing the implications of BOTH trade flows and financial flows; analysing only one flow caps at 3–4 marks, and identifying without analysing caps at 1–2. The rubric credits any valid mechanism (technology, capital transfer, free trade agreements, financial deregulation, TNCs), not only the guideline's list. Trade diversion is a cost of blocs, not a growth mechanism, and should not be used as a positive driver here." }],
  [`${U}.s057`, { modelAnswer: "One reason is to achieve a reduction in protection in order to promote economic growth: a bilateral agreement removes or lowers tariffs and other barriers between the two countries, so exports to the partner rise, domestic industries gain access to a larger market and become more efficient, and the country's output and growth increase. Alternatively, a country may seek increased exports to improve external stability or lower-priced imports to reduce inflation.", rubric: ["1. Outlines ONE reason a country enters a bilateral trade agreement with a major trading partner (e.g. achieve a reduction in protection to promote economic growth; increase exports to improve external stability; reduce domestic prices to reduce inflation; increase competitiveness/efficiency).", "2. Gives some detail explaining the reason (e.g. tariff removal opens the partner's market, raising exports and growth)."], notes: "Only one reason is needed for the marks, but it must be outlined (sketched in general terms with content). The school's acceptable reasons are: reduction in protection to promote economic growth, increased exports for external stability, lower domestic prices to reduce inflation, and increased competitiveness/efficiency. Naming \"a bilateral trade agreement\" without a reason earns nothing." }],
  [`${U}.s058`, { modelAnswer: "A bilateral trade agreement is an agreement between two countries, which reduce or remove protection on trade between them to promote trade, for example the Australia–USA FTA. A multilateral trade agreement is between three or more countries, for example AANZFTA (Australia, New Zealand and ASEAN); it is generally more favourable because it opens trade among a greater number of countries, creating larger markets and more trade than a bilateral arrangement.", rubric: ["1. Correctly indicates that a bilateral trade agreement is between two countries and involves reducing or removing protection between them (e.g. Australia–USA).", "2. Correctly indicates that a multilateral trade agreement is between three or more countries and yields more trade across a greater number of partners (e.g. AANZFTA)."], notes: "The mark requires the structural difference (number of countries), not just that both are trade agreements. Describing only one type earns 1 mark. Examples are not required but support the distinction; any correct pair of examples (e.g. EU, ASEAN, RCEP as multilateral) is acceptable." }],
  [`${U}.s059`, { modelAnswer: "Environmental sustainability means that individuals, firms and governments use natural resources in such a way that they are not diminished for future generations — meeting the needs of the present without compromising the ability of future generations to meet their own needs.", rubric: ["1. Outlines what is meant by environmental sustainability (e.g. the use of natural resources so they are not diminished for future generations; development that meets present needs without compromising future needs)."], notes: "The single mark requires a general outline, so the idea of sustaining natural resources for future generations must appear. Defining \"sustainability\" vaguely (e.g. \"looking after the environment\") without the future-generations element earns nothing beyond a sketchy relevant statement." }],
  [`${U}.s060`, { modelAnswer: "In the short term, continuing world economic development deteriorates the environment: higher economic growth raises production and consumption, using more natural resources such as minerals and fossil fuels, and generating more pollution and greenhouse gas emissions, as resources are drawn into production to satisfy rising consumer demand. In the long term, once economic growth and development have raised incomes, economies are better able to invest back into the environment through sustainable practices such as fish farming and crop-rotation techniques, the expansion of renewable energy, and cleaner technology, so environmental degradation can slow and the environment can recover. The overall impact therefore depends on whether the growth generated by development funds the transition to sustainable production.", rubric: ["1. Explains a short-term environmental impact of continuing world economic development (e.g. pollution and the depletion of natural resources such as minerals as production expands to meet demand).", "2. Explains the short-term mechanism (rising production and consumption to achieve growth and development use more resources and generate more emissions).", "3. Explains a long-term environmental impact (e.g. rising incomes allow investment in sustainable practices, renewable energy and cleaner technology so the environment recovers).", "4. Links the short-term and long-term effects with an overall explanation (e.g. short-term deterioration, then long-term recovery if growth funds sustainable practices)."], notes: "The top band requires both the short term AND the long term; covering only one caps the answer at 2 marks. The school's line is short-term deterioration (pollution, resource depletion) giving way to long-term recovery as higher incomes fund sustainable practices. A one-sided answer claiming development only ever damages the environment loses the long-term marks." }],
  [`${U}.s061`, { modelAnswer: "Free trade gives Australian consumers access to a wider range of goods and services at lower prices, because imports from countries where goods can be produced more cheaply compete with local products. This competition puts downward pressure on prices and increases the variety and quality of goods available, so consumers' real purchasing power rises.", rubric: ["1. Outlines one benefit of free trade for Australian consumers (e.g. access to a wider range of goods and services; lower prices for goods and services).", "2. Gives some detail that constitutes the outline (e.g. import competition keeps prices down and increases variety, so the real purchasing power of consumers rises)."], notes: "Only one benefit is required for the mark structure, but the top mark needs it outlined (a general sketch with some content). Naming \"cheaper goods\" alone without explaining why (competition from lower-cost imports raising variety and choice) earns at most 1 mark. The benefit must be to consumers — benefits to producers or the economy generally (e.g. export growth) do not directly answer the question." }],
  [`${U}.s062`, { modelAnswer: "Free trade is international trade conducted without artificial barriers such as tariffs, quotas or subsidies, so prices reflect comparative advantage and resources are allocated to where they are used most efficiently. Protection is the use of government measures — tariffs, quotas, subsidies, local content rules and export incentives — to restrict or discourage imports and shield domestic industries from foreign competition. The key difference is that free trade lets market forces determine what is produced and traded, maximising world output and efficiency, whereas protection deliberately interferes with those forces to shelter domestic producers, usually at the cost of higher prices for consumers and a less efficient allocation of resources.", rubric: ["1. Defines free trade (trade without artificial barriers such as tariffs, quotas or subsidies; prices reflect comparative advantage and resources are allocated efficiently).", "2. Defines protection (government measures — tariffs, quotas, subsidies, local content rules — that restrict imports or assist domestic producers against foreign competition).", "3. States the distinction between the two (free trade relies on market forces and efficiency, while protection deliberately interferes with trade to support domestic industries, typically raising prices and misallocating resources)."], notes: "The mark structure needs both clear definitions and the contrast between them: defining both earns the first two marks and the explicit distinction the third. Confusing the two, or describing protection as \"any government help for business\" without the import-restricting element, caps the answer at 2 marks. The school has no usable MG (the paper's answer guide is for a different version), so the distinction is built from 04-key-content.md definitions." }],
  [`${U}.s063`, { modelAnswer: "One benefit of using tariffs is that they provide short-term protection of domestic employment: by raising the price of imports, a tariff makes domestic products relatively cheaper, allowing domestic firms to compete and maintain jobs that would otherwise be lost to imports. One cost is decreased allocative efficiency: resources are diverted into industries in which the country does not have a comparative advantage, protecting inefficiency and reducing the long-term growth of the economy.", rubric: ["1. Outlines one benefit of using tariffs (e.g. short-term protection of domestic employment; protection against dumping; a source of government revenue).", "2. Outlines one cost of using tariffs (e.g. decreased allocative efficiency; protection of inefficiency; long-term reduction in growth; retaliation by trading partners; difficulty of removal)."], notes: "Both a benefit AND a cost are needed for 2 marks; outlining only one side earns 1 mark. The school's guideline lists benefits as short-term protection of employment, protection against dumping, and a source of government revenue, and costs as decreased allocative efficiency, protection of inefficiency, long-term reduction in growth, retaliation, and difficulty in removal — any one of each is acceptable. Naming a tariff effect without linking it to a benefit or cost is not enough." }],
  [`${U}.s064`, { modelAnswer: "China has used expansionary policy, particularly fiscal stimulus, to respond to downswings in the international business cycle. During the 2008–09 global financial crisis, when the downturn in the United States and other advanced economies cut demand for China's exports, the Chinese government launched a large fiscal stimulus package directed at infrastructure and domestic demand, and eased monetary policy to support growth. It did the same again in 2020, responding to the COVID-induced global recession with stimulus measures and credit expansion to maintain domestic demand and growth. In the longer term, China has pursued policies aimed at insulating the economy from global fluctuations — increasing domestic consumption, developing trading relationships with faster-growing partners through initiatives such as the Belt and Road Initiative, and investing in technology and innovation — so that fluctuations in the international business cycle have less effect on Chinese growth.", rubric: ["1. Names an economy other than Australia and identifies a fluctuation in the international business cycle (e.g. the 2008–09 GFC downswing; the COVID recession of 2020).", "2. Explains a specific government policy response to that fluctuation (e.g. fiscal stimulus, monetary easing, increases in domestic demand; a specific program).", "3. Gives evidence linking the fluctuation and the policy response (e.g. the GFC stimulus directed at infrastructure and domestic demand; the 2020 stimulus and credit expansion).", "4. Explains a further/longer-term policy response showing how the government responds to the international business cycle (e.g. the Belt and Road Initiative, investment in technology, building domestic demand to insulate the economy)."], notes: "Any economy other than Australia is acceptable; the rubric does not require China. The school's marking rewards specific policies with evidence for both the fluctuation and the response; generalised statements about globalisation and the country's economic policies cap the answer at 1 mark. Currency manipulation is a weak answer for this question — the school notes it is a policy to maximise trade rather than a response to fluctuations in the IBC, so it should not be used as the main response. Responses about Australia earn nothing." }],
  [`${U}.s065`, { modelAnswer: "Trade-to-GDP ratio = (exports + imports) ÷ GDP × 100. Year 1: (120 + 130) ÷ 500 × 100 = 250 ÷ 500 × 100 = 50%. Year 2: (150 + 160) ÷ 500 × 100 = 310 ÷ 500 × 100 = 62%.", rubric: ["1. Calculates the Year 1 trade-to-GDP ratio as 50% (250 ÷ 500 × 100).", "2. Calculates the Year 2 trade-to-GDP ratio as 62% (310 ÷ 500 × 100)."], notes: "The trade-to-GDP (openness) ratio is exports plus imports as a share of GDP. A student who adds only exports (or only imports) and divides by GDP earns no mark for that year. Correct method with a minor arithmetic slip earns at most 1 mark. Units (%) are not required for the mark but the ratio must be expressed as a percentage or equivalent fraction." }],
  [`${U}.s066`, { modelAnswer: "Country B's trade openness has risen, with exports rising from 20% to 33% of GDP, and its financial integration has deepened, with FDI inflows rising from 1.0% to 5.0% of GDP. This means Country B has become more interdependent with the global economy: a larger share of its output is now sold to the world, and a larger share of its investment is financed from abroad, so it is more exposed to changes in world demand and global financial conditions.", rubric: ["1. Uses the data to state that Country B's trade openness has risen (exports up from 20% to 33% of GDP).", "2. Uses the data to state that Country B's financial integration has deepened (FDI inflows up from 1.0% to 5.0% of GDP).", "3. Explains that this means greater interdependence — more exposure to world demand and global financial conditions."], notes: "A correct answer must use the data (quote the figures) and link the rising trade and financial flows to greater interdependence. Stating the figures without explaining what they mean for interdependence earns at most 2 marks. Saying the economy is \"more globalised\" without connecting it to trade and financial flows earns at most 1 mark. A claim that interdependence has fallen, or that only trade (not finance) matters, earns nothing for the relevant point." }],
  [`${U}.s067`, { modelAnswer: "Country C has become far more interdependent with the global economy than Country D. Country C's trade openness rose sharply, with exports up from 15% to 40% of GDP and imports from 17% to 42%, while its financial integration deepened even more, with FDI inflows up from 1.0% to 7.0% and portfolio inflows from 0.5% to 5.0% of GDP. Country D's trade shares rose only 3 points each and its financial flows barely moved. This means Country C now sells and buys a much larger share of its output internationally and finances a much larger share of its investment from abroad, so it is far more exposed to world demand and global financial conditions than Country D, whose integration has changed little.", rubric: ["1. Uses the data to show Country C's trade openness rose sharply (exports 15%→40%, imports 17%→42% of GDP).", "2. Uses the data to show Country C's financial integration deepened sharply (FDI 1.0%→7.0%, portfolio 0.5%→5.0% of GDP).", "3. Uses the data to show Country D's trade and financial flows changed little (exports 25%→28%, FDI 2.0%→2.5%).", "4. Makes a judgement on the extent of interdependence: Country C is far more interdependent (more exposed to world demand and global financial conditions) than Country D."], notes: "\"Analyse\" requires both the data and a judgement on the extent of interdependence. A correct answer must compare the two countries and conclude that Country C is more interdependent. Listing the figures without a comparative judgement earns at most 3 marks. A judgement with no data earns at most 1 mark. Treating trade and finance as interchangeable, or ignoring the financial flows, loses the relevant point. A claim that Country D is more interdependent (or that the two are equal) earns nothing for the judgement point." }],
  [`${U}.s068`, { modelAnswer: "The G20 is a forum of the world's largest economies (the 19 largest economies plus the EU, and the African Union since 2023) that meets to coordinate global economic policy. Its role is to bring the major economies together to agree a shared response to global economic issues and shocks — such as the coordinated fiscal stimulus after the 2008 global financial crisis — and to boost confidence and stability, even though its agreements are not legally binding.", rubric: ["1. Outlines one role of the G20 (e.g. coordinating global economic policy among the world's largest economies, or providing a shared response to global shocks).", "2. Adds a supporting detail (e.g. its membership of the largest economies, or a specific example such as the 2009 coordinated response to the GFC, or that its agreements are not binding)."], notes: "A correct answer must identify the G20 as a forum that coordinates policy, not as an organisation that lends or legislates. Naming the G20 without a role earns nothing. Calling it a trading bloc or a monetary union earns nothing. A role with no supporting detail earns 1 mark." }],
  [`${U}.s069`, { modelAnswer: "A government economic forum such as the G20 is an informal meeting of heads of government and economy ministers that coordinates policy but has no permanent secretariat and cannot make binding decisions. An international organisation such as the IMF is a formal, permanent body with its own staff and rules that carries out specific functions — the IMF lends to countries in balance-of-payments crisis and attaches conditions to that lending. The key difference is that a forum coordinates and persuades, while an organisation acts and can bind through its lending conditions.", rubric: ["1. States that a forum (e.g. the G20) is an informal meeting that coordinates policy and has no binding decisions or permanent secretariat.", "2. States that an international organisation (e.g. the IMF) is a formal, permanent body with specific functions (e.g. lending with conditionality).", "3. Identifies the distinguishing feature (a forum coordinates without binding, while an organisation acts and can bind through its rules or lending conditions)."], notes: "Both sides must be described for full marks; describing only the forum or only the organisation earns at most 1 mark. The distinction must be structural (informal/non-binding vs formal/binding), not just \"one is bigger\" or \"one meets more often\". Swapping the roles (saying the G20 lends, or the IMF only coordinates) earns nothing for the relevant point." }],
  [`${U}.s070`, { modelAnswer: "The G20 has significant influence on the global economy because it brings together the world's largest economies, which together account for about 85% of world output and about 75% of global trade, so a coordinated position carries real weight. Its influence is shown by the 2009 London Summit, where G20 leaders agreed a coordinated fiscal stimulus in response to the global financial crisis, which supported demand and helped restore confidence and stability. However, its influence is limited because it is a forum with no permanent secretariat and no power to bind its members, so its agreements depend on members actually following through, and it cannot enforce compliance the way the IMF or WTO can.", rubric: ["1. States a source of the G20's influence (e.g. its members account for about 85% of world output and 75% of global trade).", "2. Provides a specific example of G20 influence (e.g. the 2009 coordinated fiscal stimulus in response to the GFC).", "3. Explains how that example influenced the global economy (e.g. supported demand and restored confidence and stability).", "4. Makes a judgement on the limits of that influence (e.g. it is non-binding, with no enforcement power, so it depends on members' follow-through)."], notes: "\"Assess\" requires a judgement, so a correct answer must give both the influence and its limits. A description of the G20 with no example and no judgement earns at most 1 mark. An example with no explanation of its effect earns at most 2 marks. Saying the G20 \"legislates\" or \"enforces\" its decisions earns nothing for the relevant point, because it is a non-binding forum. Any well-documented G20 action (e.g. the 2009 GFC response, the 2020 COVID response) is acceptable." }],
  [`${U}.s071`, { modelAnswer: "China has used export-oriented industrialisation, combined with special economic zones, to promote growth and development. From the late 1970s it opened special economic zones such as Shenzhen, which offered tax breaks and streamlined regulation to attract foreign direct investment, and it used its low-cost labour to produce manufactured goods for world markets. This strategy raised growth and employment, lifted more than 800 million people out of poverty, and raised China's HDI, although it also increased inequality and environmental damage.", rubric: ["1. Names an economy other than Australia and identifies one development strategy it used (e.g. China's export-oriented industrialisation and special economic zones).", "2. Explains how the strategy works to promote growth and development (e.g. attracting FDI and exporting manufactured goods raises output, employment and incomes).", "3. Adds a specific detail or outcome (e.g. more than 800 million people lifted out of poverty, or a rising HDI, or a trade-off such as inequality or environmental damage)."], notes: "Any suitable economy other than Australia is acceptable (China, India, Vietnam, South Korea, Indonesia, etc.); the rubric does not require a specific one. A correct answer must name the economy, name a genuine strategy, and explain its mechanism. Naming a strategy without explaining how it works earns at most 1 mark. A generic answer with no named economy earns nothing. Quoting growth data without linking it to development (living standards/HDI) earns at most 2 marks." }],
  [`${U}.s072`, { modelAnswer: "Export-oriented industrialisation is more likely to promote growth and development in Country E. Because Country E's domestic market is small, import substitution would leave its protected firms unable to reach economies of scale and with no competitive pressure to become efficient, so they would stay high-cost and uncompetitive. By contrast, opening to foreign direct investment and exporting would let Country E use its abundant low-cost labour to produce for large world markets, attracting capital and technology it lacks, which would raise output, employment and incomes. The main trade-off is that export-led growth can increase inequality and environmental damage, and it exposes the economy to world demand, but for a small, labour-abundant economy these costs are outweighed by the gains in growth and development.", rubric: ["1. States a judgement on which strategy is more likely to promote growth and development (export-oriented industrialisation).", "2. Explains why import substitution is less suitable for Country E (small market means no economies of scale and no competitive pressure).", "3. Explains why export orientation suits Country E (uses low-cost labour for world markets and attracts the capital and technology it lacks).", "4. Identifies a trade-off or limitation of the chosen strategy (e.g. inequality, environmental damage, or exposure to world demand)."], notes: "\"Evaluate\" requires a judgement with reasons, so a correct answer must choose a strategy and justify it against Country E's characteristics (small market, low-cost labour, limited capital). A description of both strategies with no judgement earns at most 2 marks. A judgement with no reference to Country E's characteristics earns at most 2 marks. Arguing for import substitution without addressing the small-market problem earns nothing for the judgement point. The answer must be about Country E (the hypothetical economy), not a real country." }],
  [`${U}.s073`, { modelAnswer: "GWP measured at market exchange rates converts each country's output into a common currency (US dollars) using the going exchange rate, which understates emerging economies because their goods and services are cheap. GWP measured at purchasing power parity instead compares output using the prices of a common basket of goods, so it reflects real purchasing power and gives emerging economies a larger share of world output. This is why world GWP is substantially larger on a PPP basis than at market exchange rates, and why China's share of world output is larger at PPP than at market rates.", rubric: ["1. States that market-exchange-rate GWP converts output using exchange rates, while PPP GWP compares output using a common basket of prices (real purchasing power).", "2. Explains the consequence: PPP gives emerging economies a larger share of world output (because their prices are lower), so PPP GWP is larger than market-rate GWP."], notes: "Both measures must be described for full marks; describing only one earns 1 mark. The key point is the price basis (exchange rates vs a common basket of prices), not the coverage of goods. Saying the two measures are the same, or that market rates overstate emerging economies, earns nothing for the relevant point. The exact dollar figures are not required, but a correct answer should note that PPP GWP is larger." }],
]);

export const answers: AnswerSet = withWrongExplanations(keyWithoutExplanations, questions, U, explanations, 3);
